nodes.statement:
The Siegel--Walfisz theorem states that uniformly for $q\le (\log{x})^A$ and $(a,q)=1$

\begin{equation}
\pi(x;q,a)=\Bigl(1+O_A\Bigl(\frac{1}{(\log{x})^A}\Bigr)\Bigr)\frac{\pi(x)}{\phi(q)}. \end{equation}

For the purpose of many applications, an adequate substitute for the Generalized Riemann Hypothesis is the Bombieri--Vinogradov Theorem \cite{Bombieri,Vinogradov}. This states that for every $A>0$ and $B=B(A)$ sufficiently large in terms of $A$ we have

\begin{equation}
\sum_{q\le x^{1/2}/(\log{x})^B}\,\sup_{(a,q)=1}\Bigl|\pi(x;q,a)-\frac{\pi(x)}{\phi(q)}\Bigr|\ll_A\frac{x}{(\log{x})^A}. \end{equation}

For notational convenience set $D_1:=x^{2\delta+\eta}/2$ and $D_2:=\min(x^{1/10-7\delta/5-\eta},x^{1/2-19\delta-\eta})$. By considering the $d$ in dyadic ranges we see that
\begin{align*}
\mathcal{Q}_{\delta,\eta}&\subseteq \bigcup_{\substack{D=2^j\\ D_1\le D\le D_2}}\Bigl\{q\le x^{1/2+\delta}:\,\exists d|q \text{ s.t. }d\in[D,2D]\Bigr\}\\
&=\bigcup_{\substack{D=2^j\\ D_1\le D\le D_2}}\Bigl\{q_1q_2\le x^{1/2+\delta}:\,q_1\in[D,2D]\Bigr\}.
\end{align*}

We now set $Q_1:=2D$ and $Q_2:=x^{1/2+\delta}/D$, noting that if $q_1q_2\le  x^{1/2+\delta}$ and $q_1\in[D,2D]$ then $q_1\le Q_1$ and $q_2\le Q_2$. If $D_1\le D \le D_2$ we have
\begin{align*}
Q_1Q_2^2&=2\frac{x^{1+2\delta}}{D}\ll x^{1-\eta},\\
Q_1^{12}Q_2^7&=2^{12}D^5 x^{7/2+7\delta}\ll x^{4-5\eta},\\
Q_1^{20}Q_2^{19}&=2^{20}D x^{19/2+19\delta}\ll x^{10-\eta}.
\end{align*}

Thus, by the union bound and applying Theorem \ref{thrm:MainTheorem} (with $\epsilon=\eta/101$) we see that
\begin{align*}
\sum_{\substack{q\in \mathcal{Q}_{\delta,\eta}\\ (q,a)=1}}\Bigl|\pi(x;q,a)-\frac{\pi(x)}{\phi(q)}\Bigr|&\ll (\log{x})\sup_{D_1\le D\le D_2}\sum_{q_1\le 2D}\sum_{q_2\le  x^{1/2+\delta}/D}\Bigl|\pi(x;q_1q_2,a)-\frac{\pi(x)}{\phi(q_1q_2)}\Bigr|\\
&\ll_{a, A,\eta} \frac{x}{(\log{x})^A}.\qedhere
\end{align*}

Thus we see that for $\epsilon$ small enough and $x$ large enough
\begin{align*}
\sum_{\substack{q\in [Q,2Q]\backslash\mathcal{Q}_{\delta,\eta}\\ (q,a)=1}}1\le \sum_{\substack{m_1\le x^{(2+\epsilon)\delta} \\ (m_1,a)=1}}\sum_{\substack{Q/m_1\le m_2\le 2Q/m_1\\ P^-(m_2)\ge (Q/m_1)^{1/7}}}1&= \sum_{\substack{m_1\le x^{(2+\epsilon)\delta}\\ (m_1,a)=1}}\frac{(7\omega(7)+o(1))Q}{m_1\log(Q/m_1)}\\
&\le \frac{\phi(a)}{a}\frac{(4+o(1))Q(2+\epsilon)\delta}{1/2-(2+\epsilon)\delta}\le 18\frac{\phi(a)\delta Q}{a}.
\end{align*}

Define $S_n$ and $S_d(z)$ (depending on integers $a,q_1,q_2$ satisfying $(a,q_1q_2)=1$ which we suppress from the notation for convenience) for integers $n,d$ and a real $z$ by
\begin{align*}
S_n&:=\mathbf{1}_{n\equiv a\Mod{q_1q_2}}-\frac{1}{\phi(q_1q_2)}\mathbf{1}_{(n,q_1q_2)=1},\\
S_d(z)&:=\sum_{\substack{n\sim x/d\\ P^-(n)>z}}S_{d n}.
\end{align*}

We first establish some notation. Let $z_1,z_2,z_3$ be defined in terms of $x$ by
\begin{align*}
z_1&:= x^{1/7+10\epsilon},&\qquad z_2&:=x^{3/7+\epsilon},&\qquad z_3:=x^{4/7-\epsilon}.
\end{align*}
For the purposes of this section (but this section only), we assume that the symbols $r,s,t,u,v$ represent prime numbers, in the same manner that we use the symbol $p$.

Our goal is to estimate
\begin{equation}
\sum_{q_1\sim Q_1}\sum_{\substack{q_2\sim Q_2\\ (q_1q_2,a)=1}}|S_1(2x^{1/2})|=\sum_{q_1\sim Q_1}\sum_{\substack{q_2\sim Q_2\\ (q_1q_2,a)=1}}\Bigl|\sum_{\substack{p\sim x\\ p\equiv a\Mod{q_1q_2}}}1-\frac{1}{\phi(q)}\sum_{\substack{p\sim x\\ (p,q_1q_2)=1}}1\Bigr| \end{equation}
by decomposing $S_1(2x^{1/2})$ into terms which can be handled by one of Proposition \ref{prpstn:TypeII2}, Proposition \ref{prpstn:SieveAsymptotic}, Proposition \ref{prpstn:4Primes} or Proposition \ref{prpstn:3Primes}.

By Buchstab's identity
\begin{align}
S_1(2x^{1/2})&=S_1(z_1)-\sum_{z_1< p\le z_2}S_p(p)-\sum_{z_2< p\le 2x^{1/2}}S_p(p). \end{align}
By Proposition \ref{prpstn:SieveAsymptotic}, the first term on the right hand side of \eqref{eq:Decomp0} makes a negligible contribution to \eqref{eq:Target} (i.e. a contribution of size $O_{A}(x/(\log{x})^A)$ when summed with absolute values over $q_1$ and $q_2$). Similarly, by Proposition \ref{prpstn:TypeII2}, the last term also contributes negligibly. Thus we are left to consider the middle term.

We now consider the fourth term of \eqref{eq:Decomp1}. By Buchstab's identity again, we have
\begin{equation}
\sum_{\substack{z_1< r\le p\le z_2\\ z_3<p r\\  r\le x^{1/4}}}S_{p r}(r)=\sum_{\substack{z_1< r\le p\le z_2\\ z_3<p r\\  r\le x^{1/4}}}S_{p r}(z_1)-\sum_{\substack{z_1< s\le r\le p\le z_2\\ z_3<p r\\  r\le x^{1/4}}}S_{p r s}(s). \end{equation}
In the first term above we note that since $r\le x^{1/4}$ and $p\le z_2=x^{3/7+\epsilon}$ we have $p r< x^{19/28+\epsilon}<x^{2/3}$. Thus the first term of \eqref{eq:Decomp3} contributes negligibly to \eqref{eq:Target} by Proposition \ref{prpstn:SieveAsymptotic}. In the final term of \eqref{eq:Decomp3}, we see that since $p r\ge z_3$ and $s\ge z_1$, we have that $s\ge (2x/p r s)^{1/2}$, and so this counts products of exactly four primes. Thus this term also contributes negligibly to \eqref{eq:Target} by Proposition \ref{prpstn:4Primes}.

Finally, we consider the second term of \eqref{eq:Decomp1}. By Buchstab's identity, we have
\begin{align}
\sum_{\substack{z_1< r\le p\le z_2\\ p r\le z_2}}S_{p r}( r)&=\sum_{\substack{z_1< r\le p\le z_2\\ p r\le z_2}}S_{p r}(z_1)-\sum_{\substack{z_1< s\le r\le p\le z_2\\ p r\le z_2}}S_{p r s}(s). \end{align}
The first term of \eqref{eq:Decomp2} makes a negligible contribution to \eqref{eq:Target} by Proposition \ref{prpstn:SieveAsymptotic}. For the final term of \eqref{eq:Decomp2} we apply Buchstab's identity once more,
 giving
\begin{align}
\sum_{\substack{z_1< s\le r\le p\le z_2\\ p r\le z_2}}S_{p r s}(s)&=\sum_{\substack{z_1< s\le r\le p\le z_2\\ p r\le z_2}}S_{p r s}(z_1)-\sum_{\substack{z_1< t\le s\le r\le p\le z_2\\ p r\le z_2}}S_{p r s t}(t) \end{align}
In the first term of \eqref{eq:Decomp4}, we have $p r s\le (p r)^{3/2}\le z_2^{3/2}\le x^{2/3}$ and $s\le x^{1/4}$. Therefore by Proposition \ref{prpstn:SieveAsymptotic} this term makes a negligible contribution to \eqref{eq:Target}. We see that the second term of \eqref{eq:Decomp4} counts products of exactly 5 or 6 primes. Specifically
\begin{equation}
\sum_{\substack{z_1< t\le s\le r\le p\le z_2\\ p r\le z_2}}S_{p r s t}(t)=\sum_{\substack{z_1< t\le s\le r\le p\le z_2\\ p r\le z_2\\ p r s t u\sim x}}S_{p r s t u}+\sum_{\substack{z_1< t\le s\le r\le p\le z_2\\ p r\le z_2\\ t< u\le v\\ p r s t u v\sim x}}S_{p r s t u v}. \end{equation}
Thus Proposition \ref{prpstn:4Primes} shows that both of the terms  in \eqref{eq:Decomp6} contribute negligibly to \eqref{eq:Target}. Thus all the terms in \eqref{eq:Decomp2} contribute negligibly to \eqref{eq:Target}.

If $L\le K\le (L K)^{5/8}$ we see that
\begin{align*}
K^3L^4+K^2L^5&\ll K^3L^4\le (KL)^{7/2}\le x^{2-3\epsilon},\\
K^3L^2 &\le (KL)^{2+5/8}\le x^{(4/7-\epsilon)\cdot 21/8}< x^{3/2-2\epsilon}.
\end{align*}
Thus Lemma \ref{lmm:BFITripleRough} gives the result in this case.

After relabeling the indices $\{1,\dots,k\}$ (noting that this removes the property $M_1\ge \dots\ge M_k$) we may assume that $N^{1/4}\le M_1\cdots M_J\le N^{1/2}\le M_{J+1}\cdots M_k\le N^{3/4}$. We now consider $L\asymp M_1\cdots M_J$ and $K\asymp M_{J+1}\cdots M_k$ and
\begin{align*}
\alpha_m&:=\sum_{\substack{m=m_{k+1}\cdots m_r\\ m_i\in \mathcal{I}_i\forall k+1\le i\le r}}\beta^{(k+1)}_{m_{k+1}}\cdots \beta^{(r)}_{m_r},\qquad \lambda_\ell:=\sum_{\substack{\ell=m_1\cdots m_J\\ m_i\in\mathcal{I}_i\forall 1\le i \le J}}\beta^{(1)}_{m_1}\cdots \beta^{(J)}_{m_J},\\
\eta_k&:=\sum_{\substack{k=m_{J+1}\cdots m_k\\ m_i\in\mathcal{I}_i\forall J+1\le i \le k}}\beta^{(J+1)}_{m_{J+1}}\cdots \beta^{(k)}_{m_k}.
\end{align*}

This covers the range $x^{1-\epsilon}/(Q_1Q_2)<N\le x^\epsilon Q_1 Q_2$ provided
\begin{align*}
Q_1Q_2^2&<x^{1-16\epsilon}.
\end{align*}
This is condition \eqref{eq:Cons1}, and so gives the result.

\textbf{Case 2: $J=5$.}

Since $P_i\ge x^{1/7+10\epsilon}$ for all $i$, we have that $P_3P_4P_5>x^{3/7+\epsilon}$, so the result follows from Proposition \ref{prpstn:TypeII} unless $P_3P_4P_5>x^{4/7-\epsilon}$. 

We now wish to apply Proposition \ref{prpstn:TripleRough} with $K\asymp P_4 P_5$, $L=P_3$ and $M\asymp P_1P_2$ and
\begin{align*}
\eta_k:=\sum_{\substack{k=p_4 p_5\\ p_4\in \mathcal{I}_4\\ p_5\in\mathcal{I}_5}}1,\qquad \lambda_\ell:=\sum_{\substack{p_3=\ell\\ p_3\in\mathcal{I}_3}}1,\qquad \alpha_m:=\sum_{\substack{m=p_1p_2\\ p_1\in\mathcal{I}_1\\ p_2\in\mathcal{I}_2}}1.
\end{align*}
We see that since $P_5\le P_4\le P_3\le P_2\le P_1$, $P_3 P_4 P_5>x^{4/7-\epsilon}$ and $Q_1Q_2<x^{9/17-5\epsilon}$ we have
\begin{align*}
Q_1Q_2 x^{2\epsilon}&<x^{4/7-\epsilon}<P_3 P_4 P_5 \ll  L K,\\
Q_1Q_2 K&<x^{4/7}(P_1P_2P_3P_4P_5)^{2/5}\ll x^{34/35}<x^{1-2\epsilon},\\
(Q_1Q_2)^{1/7} K L&<x^{4/49}(P_1P_2P_3P_4P_5)^{3/5}\ll x^{3/5+4/49}<x^{153/224-10\epsilon},\\
Q_1Q_2 K L^{4}&<x^{9/17}\frac{(P_1P_2P_3P_4P_5)^{4/3}}{(P_4P_5)^{1/3}}\ll x^{9/17+4/3-2/7\cdot 1/3}<x^{57/32-10\epsilon}.
\end{align*}
Thus all the conditions of Proposition \ref{prpstn:TripleRough} are satisfied, and so Proposition \ref{prpstn:TripleRough} gives the result.

We now wish to apply Proposition \ref{prpstn:TripleRough} with $K\asymp P_4 P_5$, $L=P_3$ and $M\asymp P_1P_2$ and
\begin{align*}
\eta_k:=\sum_{\substack{k=p_4 p_5\\ p_4\in \mathcal{I}_4\\ p_5\in\mathcal{I}_5}}1,\qquad \lambda_\ell:=\sum_{\substack{p_3=\ell\\ p_3\in\mathcal{I}_3}}1,\qquad \alpha_m:=\sum_{\substack{m=p_1p_2\\ p_1\in\mathcal{I}_1\\ p_2\in\mathcal{I}_2}}1.
\end{align*}

Let $T_0(n)=\mathbf{1}_{P^-(n)>z_2}$ and for each $r\ge 1$ let
\begin{align*}
T_r(n)&:=\sum_{\substack{n=p_1\cdots p_r m\\ z_2<p_r\le \ldots \le p_1\le z_1\\ p_1\cdots p_r\le y }}\mathbf{1}_{P^-(m)>z_2},\\
U_r(n)&:=\sum_{\substack{n=p_1\cdots p_r m\\ z_2<p_r\le \ldots \le p_1\le z_1\\ p_1\cdots p_r\le y }}\mathbf{1}_{P^-(m)>p_r},\\
V_r(n)&:=\sum_{\substack{n=p_1\cdots p_r m\\ z_2<p_r\le \ldots \le p_1\le z_1 \\ p_1\cdots p_r> y\\ p_1\cdots p_{r-1}\le y }}\mathbf{1}_{P^-(m)>p_r}.
\end{align*}

Buchstab's identity then gives
\begin{align*}
\mathbf{1}_{P^-(n)>z_1}&=T_0(n)-U_1(n)-V_1(n),\\
U_j(n)&=T_j(n)-U_{j+1}(n)-V_{j+1}(n).
\end{align*}

Thus we obtain the result by letting
\begin{align*}
\alpha_d&:=\sum_{0\le r}(-1)^r\sum_{\substack{d=p_1\cdots p_r \\ z_2<p_r\le \dots \le p_1\le z_1}}1,\\
\beta_d&:=\sum_{1\le r}(-1)^{r}\sum_{\substack{d=p_1\cdots p_{r-1}\\ z_2<p_{r-1}\le \dots \le p_1\le z_1 }}1.
\end{align*}
Since the inner sums are zero unless $r=\Omega(d)$, in which case it is bounded by 1, we see that these are 1-bounded sequences.

The result follows from the Bombieri-Vinogradov Theorem if $Q_1Q_2\le x^{1/2-\epsilon}$, so we may assume $x^{1/2-\epsilon}\le Q_1Q_2\le x^{9/17}$. Therefore 
\begin{align*}
Q_1 Q_2 N&\le  \frac{x^{10/7+\epsilon}}{(Q_1Q_2)^{7/8}}\le x^{1-10\epsilon},\\
Q_1^2Q_2^2 N&\le x^{10/7+\epsilon}(Q_1Q_2)^{1/16}<x^{3/2-10\epsilon}.
\end{align*}

Let $y_1:=x^{1-\epsilon}/(Q_1Q_2)^{15/8}$. Since $Q_1Q_2\ge x^{1/2-\epsilon}$, we see that $y_1\le z_1$. By Lemma \ref{lmm:Buchstab} (taking $y=y_1$, $z_2=z_0$), it suffices to show that for every choice of 1-bounded coefficients $\alpha_d,\beta_d$ we have
\begin{align*}
\sum_{q_1\sim Q_1}\sum_{\substack{ q_2\sim Q_2\\ (q_1q_2,a)=1}} \Bigl|\sum_{\substack{p_1,\dots,p_r\\ p_i\in \mathcal{I}_i}}\sum_{z_0<p'\le z_1}\sum_{\substack{d\le y_1\\ P^-(d)\ge p'\\ d p'>y_1}}\beta_d\sum_{\substack{n\sim x/(d p' p_1\cdots p_r)\\ P^-(n)\ge p}}S_{n d p' p_1\cdots p_r}\Bigr|\ll \frac{x}{(\log{x})^B},\\
\sum_{q_1\sim Q_1}\sum_{\substack{ q_2\sim Q_2\\ (q_1q_2,a)=1}}\Bigl|\sum_{\substack{p_1,\dots,p_r\\ p_i\in \mathcal{I}_i}}\sum_{d\le y_1}\alpha_d\sum_{\substack{m\sim x/(d p_1\cdots p_r)\\ P^-(m)\ge z_0}}S_{m d p_1\cdots p_r}\Bigr|\ll \frac{x}{(\log{x})^B}.
\end{align*}

We set $y_1:=x^{1-\epsilon}/(Q_1Q_2)^{15/8}\le z_1$. By Lemma \ref{lmm:Buchstab} (with $y=y_1$ and $z_2=z_0$) applied to $m_1$, it suffices to show that for every 1-bounded sequence $\alpha_d$ and $\beta_d$ we have
\begin{equation}
\sum_{q_1\sim Q_1}\sum_{\substack{ q_2\sim Q_2\\ (q_1q_2,a)=1}}\Bigl(|V^{(1)}(q_1q_2)|+|T^{(1)}(q_1q_2)|\Bigr)\ll_B\frac{x}{(\log{x})^B}, \end{equation}
where
\begin{align*}
V^{(1)}(q_1q_2)&:=\sum_{\substack{m_2\in\mathcal{I}_2\\ m_3\in \mathcal{I}_3\\ P^-(m_2m_3)>z_1}}\sum_{z_0<p_1\le z_1}\sum_{\substack{d_1\le y_1\\ P^-(d_1)>p_1\\ d_1 p_1>y_1}}\beta_{d_1}\sum_{\substack{d_1 p_1 n_1\in \mathcal{I}_1\\ P^-(n_1)\ge p_1}}S_{n_1 d_1 p_1 m_2 m_3},\\
T^{(1)}(q_1q_2)&:=\sum_{\substack{m_2\in\mathcal{I}_2\\ m_3\in \mathcal{I}_3\\ P^-(m_2m_3)>z_1}}\sum_{d_1\le y_1}\alpha_{d_1}\sum_{\substack{d_1 n_1\in \mathcal{I}_1\\ P^-(n_1)\ge z_0}}S_{n_1 d_1 m_2 m_3}.
\end{align*}
We let $e=1$, $d=d_1$ $p=p_1$, $\ell=n_1$ and $m=m_2m_3$. Since we only consider $d_1p_1>y_1$, and $d_1,p_1\le z_1$, we see that Proposition \ref{prpstn:VBounds} implies that the $V^{(1)}(q_1q_2)$ terms contribute negligibly to \eqref{eq:VTBound1}. Thus we are left to consider the contribution from the $T^{(1)}(q_1q_2)$ terms.

We now apply Lemma \ref{lmm:Buchstab} to the $m_2$ sum in $T^{(1)}(q_1q_2)$, this time taking $y=y_1/d_1$. Thus it suffices to show for every 1-bounded sequence $\alpha'_{d_2}$ and $\beta'_{d_2}$ that
\begin{equation}
\sum_{q_1\sim Q_1}\sum_{\substack{ q_2\sim Q_2\\ (q_1q_2,a)=1}}\Bigl(|V^{(2)}(q_1q_2)|+|T^{(2)}(q_1q_2)|\Bigr)\ll_B\frac{x}{(\log{x})^B}, \end{equation}
where
\begin{align*}
V^{(2)}(q_1q_2)&:=\sum_{\substack{d_1,n_1,n_2,m_3\\ m_3\in \mathcal{I}_3\\ d_1\le y_1\\ n_1d_1\in\mathcal{I}_1\\ P^-(n_1)>z_0\\ P^-(m_3)>z_1}}\alpha_{d_1}\sum_{z_0<p_2\le z_1}\sum_{\substack{d_2\le y_1/d_1\\ P^-(d_2)>p_2\\ d_1 d_2 p_2>y_1}}\beta'_{d_2}\sum_{\substack{d_2 p_2 n_2\in \mathcal{I}_2\\ P^-(n_2)\ge p_2}}S_{n_1 d_1 n_2 d_2 p_2 m_3},\\
T^{(2)}(q_1q_2)&:=\sum_{d_1\le y_1}\sum_{\substack{n_1d_1\in\mathcal{I}_1\\ P^-(n_1)>z_0}}\sum_{\substack{m_3\in \mathcal{I}_3\\ P^-(m_3)>z_1}}\sum_{\substack{d_2\le y_1/d_1}}\alpha_{d_1}\alpha'_{d_2}\sum_{\substack{d_2 n_2\in \mathcal{I}_2\\ P^-(n_2)\ge z_0}}S_{n_1 d_1 n_2 d_2 m_3}.
\end{align*}
Again, on letting $e=d_1$, $p=p_2$, $d=d_2$, $n=n_2$ and $m=n_1m_3$, we see that Proposition \ref{prpstn:VBounds} shows that the $V^{(2)}(q_1q_2)$ contribute suitably little to \eqref{eq:VTBound2}, so we are left to consider the $T^{(2)}$ terms.

Finally, we apply Lemma \ref{lmm:Buchstab} once more to the $m_3$ summation of $T^{(2)}(q_1q_2)$ with $y=y_1/d_1d_2$. Thus it suffices to show for every 1-bounded sequence $\alpha''_{d_3}$ and $\beta''_{d_3}$ that
\begin{equation}
\sum_{q_1\sim Q_1}\sum_{\substack{ q_2\sim Q_2\\ (q_1q_2,a)=1}}\Bigl(|V^{(3)}(q_1q_2)|+|T^{(3)}(q_1q_2)|\Bigr)\ll_B\frac{x}{(\log{x})^B}, \end{equation}
where
\begin{align*}
V^{(3)}(q_1q_2)&:=\sum_{\substack{d_1,d_2,n_1,n_2\\ d_1d_2\le y_1\\ n_1d_1\in\mathcal{I}_1\\ n_2d_2\in\mathcal{I}_2\\ P^-(n_1n_2)>z_0}}\alpha_{d_1}\alpha'_{d_2}\sum_{z_0<p_3\le z_1}\sum_{\substack{d_3\le y_1/(d_1d_2)\\ P^-(d_3)>p_3\\ d_1 d_2 d_3 p_3>y_1}}\beta''_{d_3}\sum_{\substack{d_3 p_3 n_3\in \mathcal{I}_3\\ P^-(n_3)\ge p_3}}S_{n_1n_2n_3d_1d_2d_3 p_3},\\
T^{(3)}(q_1q_2)&:=\sum_{d_1d_2d_3\le y_1}\sum_{\substack{n_1d_1\in\mathcal{I}_1\\ n_2d_2\in\mathcal{I}_2\\ P^-(n_1n_2)>z_0}}\alpha_{d_1}\alpha'_{d_2}\alpha''_{d_3}\sum_{\substack{d_3 n_3\in \mathcal{I}_3\\ P^-(n_3)\ge z_0}}S_{n_1 n_2 n_3 d_1 d_2 d_3}.
\end{align*}
Again, on letting $e=d_1d_2$, $p=p_3$, $d=d_3$, $n=n_3$ and $m=n_1n_2$, we see that Proposition \ref{prpstn:VBounds} shows that the $V^{(3)}$ terms contribute suitably little to \eqref{eq:VTBound3}, so we are left to consider the $T^{(3)}$ terms.

Finally, we split the $T^{(3)}(q_1q_2)$ sum by putting $d_1,d_2,d_3$ into short intervals $d_i\in\mathcal{J}_i=[D_i,D_i(1+\log^{-C_2}{x}) )$ for a suitably large constant $C_2=C_2(A)$. We then see by Lemma \ref{lmm:SmallSets} we may replace the constraint $d_i n_i\in \mathcal{I}_i$ by $D_i n_i\in\mathcal{I}_i$ since the contribution from near the end points is negligible. Therefore it suffices to show that for every $B>0$
\begin{equation}
\sum_{q_1\sim Q_1}\sum_{\substack{ q_2\sim Q_2\\ (q_1q_2,a)=1}}\Bigl|\sum_{\substack{d_1,d_2,d_3\\ d_1d_2d_3\le y_1\\ d_i\in\mathcal{J}_i\forall i}}\alpha_{d_1}\alpha'_{d_2}\alpha''_{d_3}\sum_{\substack{n_1,n_2,n_3\\ D_i n_i\in \mathcal{I}_i\forall i\\ P^-(n_i)>z_0\forall i}}S_{d_1d_2d_3n_1n_2n_3}\Bigr|\ll_B\frac{x}{(\log{x})^B}. \end{equation}

We first put $n$ into residue classes $\Mod{d q}$ and the apply Lemma \ref{lmm:Completion}. This gives
\begin{align*}
&\sum_{\substack{(n,q)=1\\ n\equiv n_0\Mod{d}}}f\Bigl(\frac{n}{N}\Bigr)e\Bigl(\frac{b\overline{n}}{q}\Bigr)=\sum_{\substack{c\Mod{q}\\ (c,q)=1}}e\Bigl(\frac{b\overline{c}}{q}\Bigr)\sum_{\substack{n\equiv c\Mod{q}\\ n\equiv n_0\Mod{d}}}f\Bigl(\frac{n}{N}\Bigr)\\
&=\frac{N\hat{f}(0)}{dq}\sum_{\substack{c\Mod{q}\\ (c,q)=1}}e\Bigl(\frac{b\overline{c}}{q}\Bigr)+\frac{N}{d q}\sum_{\substack{c\Mod{q}\\ (c,q)=1}}e\Bigl(\frac{b\overline{c}}{q}\Bigr)\sum_{1\le |h|\le H}\hat{f}\Bigl(\frac{h N}{d q}\Bigr)e\Bigl(h\Bigl(\frac{c \overline{d}}{q}+\frac{n_0\overline{q}}{d}\Bigr)\Bigr)\\
&\qquad +O_C(x^{-100}).
\end{align*}

We see that for any choice of $A>0$ we have
\begin{align*}
\sum_{\substack{n\sim N\\ n\equiv a\Mod{q}\\ \tau(n)\ge (\log{x})^C}}\alpha_n\le \sum_{\substack{n\le \min(2x,N) \\ P^-(n)\ge z_0}}\frac{\tau(n)^{B+A}}{(\log{x})^{AC}}\le \frac{N}{(\log{x})^{AC}}\prod_{z_0<p\le 2x}\Bigl(1+\frac{O_{A,B}(1)}{p}\Bigr)
\end{align*}

By Cauchy-Schwarz we have
\[
\sum_{q\le Q}\tau(q)^{B_0}\sum_{\substack{b\Mod{q}\\ (b,q)=1}}\Bigl|\sum_{n\sim N}\alpha_n \Bigl(\mathbf{1}_{n\equiv b\Mod{q}}-\frac{\mathbf{1}_{(n,q)=1}}{\phi(q)}\Bigr)\Bigr|^2\ll \mathscr{S}_1^{1/2}\mathscr{S}_2^{1/2},
\]
where, bounding trivially via Lemma \ref{lmm:Divisor}
\begin{align*}
\mathscr{S}_1&:=\sum_{q\le Q}\tau(q)^{2B_0}\sum_{\substack{b\Mod{q}\\ (b,q)=1}}\Bigl|\sum_{n\sim N}\alpha_n \Bigl(\mathbf{1}_{n\equiv b\Mod{q}}-\frac{\mathbf{1}_{(n,q)=1}}{\phi(q)}\Bigr)\Bigr|^2\\
&\ll N^2\sum_{q\le Q}\frac{(\tau(q)\log{x})^{O_{B_0}(1)}}{q}\ll N^2(\log{x})^{O_{B_0}(1)},
\end{align*}
and by \cite[Theorem 0]{BFI1} for any constant $C>0$
\begin{align*}
\mathscr{S}_2&:=\sum_{q\le Q}\sum_{\substack{b\Mod{q}\\ (b,q)=1}}\Bigl|\sum_{n\sim N}\alpha_n \Bigl(\mathbf{1}_{n\equiv b\Mod{q}}-\frac{1}{\phi(q)}\Bigr)\Bigr|^2\ll_C \frac{N^2}{(\log{N})^{C}}.
\end{align*}

By Lemma \ref{lmm:Divisor} we have that
\begin{align*}
\sum_{b\le  x}\gamma_b\Bigl(\mathbf{1}_{b\equiv a\Mod{q}}-\frac{\mathbf{1}_{(b,q)=1}}{\phi(q)}\Bigr)&\ll \frac{x(\log{x})^{O_{B_0}(1)}}{q}+\sum_{\substack{b\le x\\ b\equiv a\Mod{q}}}\tau(b)^{B_0}\\
&\ll \frac{x(\tau(q)\log{x})^{O_{B_0}(1)}}{q}.
\end{align*}

Let $q=q_1 q_2$ where $sq(q)=q_1$, and let $q_0$ be the radical of $q_1$, so that $q_0^2|q_1$. Then, using Lemma \ref{lmm:Divisor} again, we see that the sum in the lemma is bounded by
\begin{align*}
\sum_{\substack{q_1\ge (\log{x})^C\\ p|q_1\Rightarrow p^2|q_1}}\sum_{q_2\le 2Q/q_1}\frac{x(\tau(q_1q_2)\log{x})^{O_{B_0}(1)}}{q_1q_2}&\ll x(\log{x})^{O_{B_0}(1)}\sum_{q_0\ge (\log{x})^{C/2}}\frac{\tau(q_0)^{O_{B_0}(1)}}{q_0^2}\\
&\ll \frac{x(\log{x})^{O_{B_0}(1)}}{(\log{x})^{C/2}}.
\end{align*}

As in the proof of Lemma \ref{lmm:Squarefree}, by Lemma \ref{lmm:Divisor} we have the trivial bound
\begin{align*}
\sum_{b\le x}\gamma_b\Bigl(\mathbf{1}_{b\equiv a\Mod{q}}-\frac{\mathbf{1}_{(b,q)=1}}{\phi(q)}\Bigr)&\ll \frac{x(\tau(q)\log{x})^{O_{B_0}(1)}}{q}.
\end{align*}

We factor $q=q_1q_2$ into $z_0$-smooth and $z_0$-rough parts. Thus we see that the sum in the lemma is bounded by
\begin{align*}
\sum_{\substack{q_1\ge y_0\\ P^+(q_1)\le z_0}}\sum_{q_2\sim Q_2}\frac{x(\tau(q_1q_2)\log{x})^{O_{B_0}(1)}}{q_1q_2}&\ll x(\log{x})^{O_{B_0}(1)}\sum_{\substack{q_1\ge y_0\\ P^+(q_1)\le z_0}}\frac{\tau(q_1)^{O_{B_0}(1)}}{q_1}.
\end{align*}

Now we us Rankin's trick. Letting $\eta=1/\log{z_0}=1/(\log\log{x})^3$, we have
\begin{align*}
\sum_{\substack{q_1\ge y_0\\ P^+(q_1)\le z_0}}\frac{\tau(q_1)^{B_0}}{q_1}\le y_0^{-\eta}\sum_{P^+(q_1)\le z_0}\frac{\tau(q_1)^{B_0}}{q_1^{1-\eta}}&\ll_{B_0}  y_0^{-\eta}\prod_{\substack{p\le z_0\\ 2^{B_0+3}\le p}}\Bigl(1-\frac{2^{B_0}}{p^{1-\eta}}\Bigr)^{-1}\\
&\ll (\log{z_0})^{O_{B_0}(1)} y_0^{-1/\log{z_0}}.
\end{align*}
Since $y_0^{-1/\log{z_0}}\ll_A (\log{z_0})^{-A}$ for every $A>0$, this gives the result.

By Lemma \ref{lmm:Divisor}, the error term above contributes to $\mathscr{S}_1$ a total
\begin{align*}
&\ll \sum_{e\sim E}\sum_{q\asymp Q}\sum_{d\sim D}\sum_{r_1,r_2\sim R}\sum_{n_1,n_2\sim N}\frac{\tau( q d r_1r_2)^{2B_0+1}\tau(n_1)^{B_0}\tau(n_2)^{B_0}\log{x}}{Q^2 D^2 R^2 E}\ll \frac{N^2(\log{x})^{O_{B_0}(1)}}{Q D},
\end{align*}
which is $O_A(MN^2/(Q D(\log{x})^{2A}))$ provided
\begin{equation}
M>(\log{x})^C
\end{equation}
 and $C$ is sufficiently large in terms of $A$ and $B_0$.

Finally, we may reintroduce the condition $(e,r_1r_2)=1$ in exactly the same way that we originally removed it, at the cost of a negligible error. Thus, we see that
\begin{equation}
\mathscr{S}_{2}=\mathscr{S}_{MT}+O_{A,B_0}\Bigl(\frac{MN^2}{QD (\log{x})^{2A}}\Bigr)+O(M|\mathscr{E}_{1}|), \end{equation}
where $\mathscr{E}_{1}$ is the middle term contribution, given in the statement of the lemma.

Similarly, we restrict to $(n_1,n_2)=1$. The contribution to $\mathscr{S}_{3}$ from terms with $(n_1,n_2)>1$ is
\begin{align*}
&\ll \sum_{f>z_0}\sum_{e\sim E}\sum_{\substack{n_1\sim N\\ f|n_1}}\,\sideset{}{^*}\sum_{m\sim  M}\sum_{\substack{\ell\asymp Q D\\ \ell|mn_1-a}}\,\,\sideset{}{^*}\sum_{\substack{n_2\sim N\\ n_1\equiv n_2\Mod{\ell [e,f]}}}\sum_{r_1|m n_1-a}\sum_{r_2|m n_2-a}(\log{x})^{C_1}\\
&\ll \sum_{f>z_0}\sum_{\substack{n_1\sim N\\ f|n_1}}\sum_{m\ll  M}\sum_{e\sim E}\Bigl(\frac{(e,f)N}{Q D E z_0}+1\Bigr)(\log{x})^{3C_1}\\
&\ll  \frac{MN^2(\log{x})^{3C_1+2}}{Q D z_0}+EMN(\log{x})^{3C_1+2}.
\end{align*}

Similarly, we restrict to $(qd,r_2)=1$. Terms with $(q d,r_2)>1$ contribute a total
\begin{align*}
&\ll \sum_{e\sim E}\sum_{\substack{n_1\sim N}}\,\sideset{}{^*}\sum_{m\sim  M}\sum_{\substack{\ell\asymp Q D\\ \ell|m n_1-a\\ (\ell,a)=1}}\sum_{\substack{f>z_0\\ f|\ell}}\,\sideset{}{^*}\sum_{\substack{n_2\sim N\\ m n_2\equiv a\Mod{\ell f}\\ n_2\equiv n_1\Mod{\ell e}}}\sum_{r_1|m n_1-a}\sum_{r_2'|m n_2-a}(\log{x})^{C_1}\\
&\ll \sum_{n_1\sim N}\,\sideset{}{^*}\sum_{m\sim M}\sum_{f|mn_1-a}\sum_{e\sim E}\Bigl(\frac{N(e,f)}{Q D E z_0}+1\Bigr)(\log{x})^{3C_1}\\
&\ll  \frac{MN^2(\log{x})^{5C_1}}{Q D z_0}+E MN(\log{x})^{5C_1}.
\end{align*}

Similarly, we restrict to $|n_1-n_2|\ge N/(\log{x})^C$. Terms with $|n_1-n_2|\le N/(\log{x})^C$ contribute a total
\begin{align*}
&\ll \sum_{e\sim E}\sum_{\substack{n_1\sim N}}\,\sideset{}{^*}\sum_{m\sim  M}\sum_{\substack{\ell\asymp Q D\\ \ell|m n_1-a}}\,\sideset{}{^*}\sum_{\substack{n_2\sim N\\ n_1\equiv n_2\Mod{\ell e}\\ |n_1-n_2|\le N/(\log{x})^C}}\sum_{r_1|m n_1-a}\sum_{r_2|m n_2-a}(\log{x})^{C_1}\\
&\ll ENM(\log{x})^{C_1}\Bigl(\frac{N}{Q D E(\log{x})^C}+1\Bigr)(\log{x})^{2C_1}\\
&\ll  \frac{MN^2(\log{x})^{3C_1}}{Q D (\log{x})^C}+E MN(\log{x})^{3C_1}.
\end{align*}

Finally, we remove the condition $(e,r_1r_2)=1$. Terms with $(e_1,r_2)>1$ contribute
\begin{align*}
&\sum_{f>z_0}\sum_{\substack{e\sim E\\ f|e}}\sum_{n_1\sim N}\,\sideset{}{^*}\sum_{m\sim M}\sum_{\substack{\ell\asymp Q D\\ \ell|m n_1-a}}\sum_{\substack{n_2\sim N\\ n_2\equiv n_1\Mod{\ell e}\\ m n_2\equiv a \Mod{\ell f}}}\sum_{r_1|m n_1-a}\sum_{r_2'|m n_2-a}(\log{x})^{C_1}\\
&\ll  \,\sideset{}{^*}\sum_{m\sim M}\sum_{n_1\sim N}\sum_{\substack{f\\ f|m n_1-a}}\frac{E}{z_0}\Bigl(\frac{N}{QDE}+1\Bigr)(\log{x})^{3C_1}\\
&\ll \frac{MN^2(\log{x})^{4C_1}}{Q D z_0}+\frac{E MN(\log{x})^{4C_1}}{z_0}.
\end{align*}

Provided $C>5C_1+2A+2$ all of these are negligible. After making these restrictions, we re-insert terms with $\tau(m n_1-a)\tau(m n_2a)\ge (\log{x})^{C_1}$ and $|\alpha_{n_1}\alpha_{n_2}\eta_{q,d,r_1}\eta_{q,d,r_2}|\ge(\log{x})^{C_1}$, which we have already seen is a negligible contribution. Thus, assuming \eqref{eq:DispersionCond} holds with $C>5C_1+2A+2$, we see that 
\begin{equation}
\mathscr{S}_{3}=\mathscr{S}_{4}+O_{A,B_0}\Bigl(\frac{MN^2}{Q D (\log{x})^{2A}}\Bigr), \end{equation}
where
\begin{align*}
\mathscr{S}_{4}:=\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\\ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{d\sim D\\ (d,a)=1}}&\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q d r_1)=1}}\eta_{q,d,r_1}\overline{\eta_{q,d,r_2}} \sum_{\substack{n_1,n_2\sim N\\ (n_1,n_2 q d e r_1)=1\\(n_2,n_1 q d e r_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C\\ n_1\equiv n_2\Mod{qde}}}\alpha_{n_1}\overline{\alpha_{n_2}}\\
&\qquad\times\sum_{\substack{m\\ m n_1\equiv a\Mod{q d r_1}\\ m n_2\equiv a\Mod{q d r_2}}} \psi_0\Bigl(\frac{m}{M}\Bigr).
\end{align*}

The contribution to $\mathscr{S}_{4}$ from the first term is
\begin{align*}
M\hat{\psi}_0(0)\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\\ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q d r_1)=1}}\frac{\eta_{q,d,r_1}\overline{\eta_{q,d,r_2}} }{q d r_1 r_2}\hspace{-0.5cm}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q d e}\\ (n_1,q d e r_1)=1\\(n_2,q d e r_2)=1\\ (n_1,n_2)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\hspace{-0.5cm}\alpha_{n_1}\overline{\alpha_{n_2}}.
\end{align*}
We multiply the summand above by a factor
\[
\frac{\phi(q d e)^2\phi(q d r_1 r_2)}{\phi(q d)\phi(q d e r_1)\phi(q d e r_2)}=\prod_{\substack{p|(r_1r_2,e)\\ p\nmid qd}}\Bigl(\frac{p-1}{p}\Bigr)\prod_{\substack{p|(r_1,r_2)\\ p\nmid qde}}\Bigl(\frac{p}{p-1}\Bigr)=1+O\Bigl(\frac{\log{x}}{z_0}\Bigr),
\]
where we have used the fact that $P^-(r)\ge z_0$ from the support of $\eta$. This introduces an error term which contributes 
\begin{align*}
&\ll \frac{M \log{x}}{z_0}\sum_{e\sim E}\sum_{\substack{\ell \asymp Q D}}\sum_{\substack{r_1,r_2\sim R}}\frac{(\tau(r_1)\tau(r_2)\tau(\ell)^2)^{B_0}}{Q D R^2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{\ell e} \\ |n_1-n_2|\ge N/(\log{x})^C}}(\tau(n_1)\tau(n_2))^{B_0}\\
&\ll \frac{MN^2(\log{x})^{O_{B_0}(1)}}{Q D z_0}+\frac{E M N(\log{x})^{O_{B_0}(1)}}{z_0}.
\end{align*}
This is negligible assuming \eqref{eq:DispersionCond} holds with $C$ sufficiently large in terms of $B_0$ and $A$. Thus we see that
\begin{equation}
\mathscr{S}_{4}=\mathscr{S}_5+O(M|\mathscr{E}_2|)+O_{A,B_0}\Bigl(\frac{MN^2}{Q D (\log{x})^{2A}}\Bigr), \end{equation}
where $\mathscr{E}_2$ is is given by the statement of the lemma, and where
\begin{align*}
\mathscr{S}_5&:=M\hat{\psi}_0(0)\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\\ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_{\substack{r_1,r_2\sim R\\ (r_1,a r_2)=1\\ (r_2,a q d r_1)=1}}\\
&\qquad\times\frac{\eta_{q,d,r_1}\overline{\eta_{q,d,r_2}} \phi(q d e)^2\phi(q d r_1 r_2)}{\phi(q d)\phi(q d e r_1)\phi(q d e r_2)q d r_1 r_2}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q d e}\\ (n_1,n_2 q d e r_1)=1\\(n_2,n_1 q d e r_2)=1}}\alpha_{n_1}\overline{\alpha_{n_2}}.
\end{align*}

Since $\alpha_n$ satisfies the Siegel-Walfisz condition \eqref{eq:SiegelWalfisz}, by Lemma \ref{lmm:BarbanDavenportHalberstam} we see that (using \eqref{eq:DispersionCond}) we have
\begin{equation}
\mathscr{E}_3\ll_{A,B_0} \frac{MN^2}{Q D(\log{x})^{2A}}. \end{equation}

Similarly, the contribution with $(e,r)\ne 1$ is
\begin{align*}
&\ll \sum_{\substack{f>z_0\\ f|e}}\sum_{d\sim D}\sum_{q\sim Q}\sum_{\substack{r\sim R\\ f|r}}\sum_{m\sim M}\sum_{\substack{n\sim N}}\tau(q d r n m)^{2B_0}\Bigl(\mathbf{1}_{mn\equiv a\Mod{qdr}}+\frac{1}{\phi(qdr)}\Bigr)\\
&\ll x(\log{x})^{O_{B_0(1)}}\sum_{\substack{f>z_0\\ f|e}}\frac{\tau(f)^{O_{B_0}(1)}}{f}\\
&\ll \frac{x(\log{x})^{O_{B_0(1)}}}{z_0^{1/2}}\exp(O_{B_0}((\log{x})^{1/2}))
\end{align*}

We now apply Cauchy-Schwarz in the $e$, $b$, $m$, $q$ and $d$ variables, which allows us to eliminate the $\beta_m$ and $\gamma_{q,d}$ coefficients. This gives
\begin{align*}
|\mathscr{S}|^2
&\le \frac{1}{\mathscr{E}_0^2}\Bigl(\sum_{e\sim E}\sum_{q\sim Q} \sum_{d\sim D}\sum_{\substack{m\sim M\\ (m,q d)=1}}\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}}}|\gamma_{q,d}|^2|\beta_m|^2\Bigr)  \mathscr{S}'+O_A\Bigl(\frac{x^2}{(\log{x})^{2A}}\Bigr)\\
&\ll M Q D(\log{x})^{O_{B_0}(1)} \mathscr{S}'+O_A\Bigl(\frac{x^2}{(\log{x})^{2A}}\Bigr),
\end{align*}
where 
\begin{align*}
\mathscr{S}'&:=\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\sim Q\\ (q,a)=1}}\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_{m\sim M}\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}\\ (b,q d e )=1}}\\
&\qquad\times\Bigl|\sum_{\substack{r\sim R\\ (r,a e)=1}}\lambda_{q,d,r}\sum_{\substack{n\sim N\\ (n,e)=1}}\alpha_n\Bigl(\mathbf{1}_{\substack{m n\equiv a\Mod{q d r}\\ n\equiv b\Mod{q d e}}}-\frac{\mathbf{1}_{(m n,qd r)=1}}{\phi(q d r e)}\Bigr)\Bigr|^2.
\end{align*}

We now extend the $m$ and $q$ summations using $\psi_0$ for an upper bound, and then open out the square. This gives
\begin{align}
\mathscr{S}'&\le \sum_{\substack{q\\ (q,a)=1}}\sum_{\substack{d\sim D\\ (d,a)=1}}\sum_m \psi_0\Bigl(\frac{q}{Q}\Bigr)\psi_0\Bigl(\frac{m}{M}\Bigr)\sum_{e\sim E}\mu^2(e)\sum_{\substack{b\Mod{q d e}\\ b\equiv a\overline{m}\Mod{q d}\\ (b,q d e )=1}}\nonumber\\
&\qquad\times \Bigl|\sum_{\substack{r\sim R\\ (r,a e)=1}}\lambda_{q,d,r}\sum_{\substack{n\sim N\\ (n,e)=1}}\alpha_n\Bigl(\mathbf{1}_{\substack{m n\equiv a\Mod{q d r}\\ n\equiv b\Mod{q d e}}}-\frac{\mathbf{1}_{(m n,qd r)=1}}{\phi(q d r e)}\Bigr)\Bigr|^2\nonumber \\
&=  \mathscr{S}_{1}-2\Re(\mathscr{S}_{2})+\mathscr{S}_{3}, \end{align}
where, after performing the $b$ summation, we see that $\mathscr{S}_1,\mathscr{S}_2,\mathscr{S}_3$ are as given by Lemma \ref{lmm:Dispersion1}, \ref{lmm:Dispersion2} and \ref{lmm:Dispersion3} with $\eta_{q,d,r}:=\lambda_{q,d,r}$. These lemmas then give the result.

We first wish to simplify the exponential term in the summand. By Lemma \ref{lmm:Bezout}, we have
\begin{align*}
\frac{ah\overline{n_1 r_2}}{q r_1}&=\frac{-ah\overline{q r_1}}{n_1 r_2}+\frac{ah}{q r_1 r_2 n_1}\Mod{1}.
\end{align*}

We wish to show $\mathscr{F}_2\ll N^2/Q x^{2\epsilon}$. We apply Cauchy-Schwarz in the $q,r_1,r_2$ variables to eliminate the $\lambda_{q,r}$ coefficients, giving
\[
\mathscr{F}_2\ll \frac{|\mathscr{F}_3|^{1/2}}{Q^{1/2} R},
\]
where
\begin{align*}
\mathscr{F}_3:=\sum_{q\sim Q}\sum_{\substack{r_1,r_2\sim R\\ (r_1,r_2)=1}}\Biggl|\sum_{\substack{n\sim N\\ (n,q r_1)=1}}\sum_{\substack{N/(q\log^{C}{x})\le |k|\le K\\ n+kq\sim N\\ (n+k q,q n r_2)=1\\ (n r_2,n+k q)\in\mathcal{N}}}\sum_{1\le |h| \le H'} c_{n,k,q,h} e\Bigl( \frac{-a h k\overline{(n+kq) r_1}}{ n r_2}\Bigr)\Biggr|^2,
\end{align*}
for some 1-bounded coefficients $c_{n,k,q,h}$. We wish to show $\mathscr{F}_3\ll R^2 N^4 /Q x^{4\epsilon}$. (Here we have extended the summation of $q,r_1,r_2$ slightly for an upper bound.)

We first consider $\mathscr{F}_{\ell=0}$, the contribution from the `diagonal' terms with $\ell=0$. Since $(n_2,n_2+k_2q)=1$ we have $(k_2,n_2+k_2q)=1$ and so $k_2|h_1k_1n_2$ for these terms. Thus
\begin{align*}
\mathscr{F}_{\ell=0}&\ll \sum_{\substack{q\sim Q\\ r_1,r_2\sim R}}\sum_{\substack{|h_1|\le H\\ |k_1|\le K\\ n_2\sim N}}\sum_{k_2|h_1k_1n_2}\,\,\sum_{h_2n_1|h_1k_1n_2(n_2+k_2q)}1\\
&\ll (\log{x})^{O(1)}Q R^2 H K N\\
&\ll (\log{x})^{O(1)} \frac{Q R^4 N^2 }{M}. 
\end{align*}
This gives $\mathscr{F}_{\ell=0}\ll R^2 N^4/Q x^{4\epsilon}$ provided
\[
M>\frac{x^{6\epsilon} Q^2 R^2}{N^2}.
\]
Recalling $MN\asymp x$, this is satisfied if
\begin{equation}
Q R<x^{1/2-4\epsilon} N^{1/2}. \end{equation}

We now consider the terms with $\ell\ne 0$. We let $t=n_1n_2$ and put each of $\ell$, $t$, $s$ into one of $O(\log^3{x})$ dyadic ranges. Thus 
\begin{equation}
\mathscr{F}_{\ell\ne 0} \ll (\log{x})^3\sup_{\substack{N^2\ll S,T\ll N^2 \\ L\ll R^2 N^3(\log{x})^2/M}}\sum_{s\sim S}\sum_{t\sim T}\sum_{\ell\sim L}b_{\ell,s,t}\sum_{\substack{r_1,r_2\\ (s r_1,r_2 t)=1}}g(r_1,r_2)e\Bigl(\frac{\ell \overline{s r_1}}{r_2 t}\Bigr), \end{equation}
where $b_{\ell,s,t}$ are complex coefficients satisfying
\[
|b_{\ell,s,t}|\le \mathop{\sum_{q\sim Q}\,\, \sum_{|k_1|,|k_2|\le K}\,\,\sum_{1\le |h_1|,|h_2|\le H'}\,\,\sum_{n_1,n_2\sim N}}\limits_{\substack{\ell=a(h_1k_1n_2(n_2+k_2q)-h_2k_2n_1(n_1+k_1q))\\
s=(n_1+k_1q)(n_2+k_2q)\\ t=n_1n_2}}1.
\]
We can now apply Lemma \ref{lmm:DeshouillersIwaniec} to bound the sum \eqref{eq:FouvryOffDiag}. This gives
\begin{align*}
\mathscr{F}_{\ell\ne 0}& \ll x^\epsilon\Bigl(RT(ST+L)(R+RS)+R^3T\sqrt{(ST+L)S}+R^2LS\Bigr)^{1/2}\|b\|_2\\
&\ll x^{2\epsilon}\Biggl(R N^2\Bigl(N^4+\frac{N^3 R^2}{M}\Bigr)(R+R N^2)\\
&\qquad\qquad\qquad+R^3N^2\sqrt{\Bigl(N^4+\frac{N^3 R^2}{M}\Bigr)N^2}+R^2\frac{N^3 R^2}{M}N^2\Biggr)^{1/2}\|b\|_2.
\end{align*}
Since $MN\asymp x$, this simplifies to
\begin{align}
\mathscr{F}_{\ell\ne0}&\ll x^{2\epsilon} \Bigl(R^2 N^8+\frac{R^4 N^8}{x}+R^3N^5+\frac{R^4 N^5}{x^{1/2}}\Bigr)^{1/2}\|b\|_2. \end{align}
We first consider $\|b\|_2$. We see that
\[
\|b\|_2^2\le \sum_{\ell\sim L}\sum_{s\sim S}\sum_{\substack{t\sim T\\ (s,t)=1}}\Bigl(\sum_{\substack{n_1n_2=t\\ n_1,n_2\sim N}}\sum_{\substack{|k_1|,|k_2|\le K\\ q\sim Q \\ s=(n_1+k_1q)(n_2+k_2q)}}\#\mathcal{C}\Bigr)^2,
\]
where $\mathcal{C}=\mathcal{C}(k_1,k_2,q,n_1,n_2,\ell)$ is the set
\begin{align*}
\mathcal{C}=\{(h_1,h_2)\in [1,H]^2:&\,\ell=a(h_1k_1n_2(n_2+k_2q)-h_2k_2n_1(n_1+k_1q))\}.
\end{align*}
There are at most $\tau(t)=x^{o(1)}$ choices of $n_1,n_2$ given $t$. There are at most $\tau(s)=x^{o(1)}$ choices of $n_1+k_1q$ and $n_1+k_2q$ given $s$. There are then at most $\tau(s-n_1)\tau(s-n_2)=x^{o(1)}$ choices of $k_1,k_2,q$ given $n_1+k_1q$ and $n_2+k_2q$ and $n_1,n_2$. Thus there are at most $x^{o(1)}$ choices of $n_1,n_2,k_1,k_2,q$ given $s$ and $t$. Moreover, since $(s,t)=1$ we have $(n_1,k_1)=(n_2,k_2)=1$. Thus, by Cauchy-Schwarz, we see that
\begin{align*}
\|b\|_2^2&\ll x^{o(1)}\sum_{\ell\sim L}\sum_{s\sim S}\sum_{\substack{t\sim T\\ (s,t)=1}}\sum_{\substack{n_1n_2=t\\ n_1,n_2\sim  N}}\sum_{q\sim Q}\sum_{\substack{|k_1|,|k_2|\le K\\ s=(n_1+k_1q)(n_2+k-2q)}}\#\mathcal{C}^2\\
&\ll x^{o(1)} \mathop{\sum_{n_1,n_2,k_1,k_2,q}\,\,\sum_{h_1,h_2,h_3,h_4}}\limits_{\substack{(h_1-h_3)k_1n_2(n_2+k_2q)=(h_2-h_4)k_2n_1(n_1+k_1q)\\ (n_1,k_1)=(n_2,k_2)=1}}1.
\end{align*}
Here we have suppressed the ranges for the variables in the final line for convenience. We see that if $h_1-h_3=0$, then we must have $h_2-h_4=0$, and so the total contribution from terms with $h_1-h_3=0$ is
\begin{align}
&\ll x^{o(1)} H^2 N^2 K^2Q\ll x^{o(1)} \frac{Q^2 R^4}{M^2}N^2\frac{N^2}{Q^2}Q\ll x^{o(1)} \frac{Q R^4N^6}{x^2}. \end{align}
If instead $h_1-h_3\ne 0$, then we first fix a choice of $h_1$, $h_3$, $n_2$, $k_2$ and $q$, for which there are $O(H^2 N K Q)$ choices. Since $(k_1,n_1)=1$, we have that $n_1(n_1+k_1q)|(h_1-h_3)n_2(n_2+k_2q)$, so there are $O(x^{o(1)})$ choices of $n_1,k_1$. Given such a choice of $n_1,k_1$, we see that $(h_2-h_4)$ is uniquely determined, and so there are $O(H)$ choices of $h_2$ and $h_4$. Thus the total contribution from terms with $h_1-h_3\ne 0$ is 
\begin{equation}
\ll x^{o(1)}H^3 N K Q\ll x^{o(1)} \frac{Q R^4N^6}{x^2}\Bigl(\frac{Q^2R^2}{x N}\Bigr). \end{equation}
But we have $Q^2 R^2<x^{1-8\epsilon}N$ by \eqref{eq:FouvryCond2}, so we find that the bound \eqref{eq:bDiag} is larger than the bound \eqref{eq:bOffDiag}. Thus
\begin{equation}
\|b\|_2^2\ll x^{\epsilon}\frac{Q R^4 N^6}{x^2}. \end{equation}
Putting together \eqref{eq:bBound} and \eqref{eq:FouvryFOffDiag}, we find that
\begin{align*}
\mathscr{F}_{\ell\ne 0}&\ll x^{3\epsilon}\Bigl(R^2 N^8+\frac{R^4 N^8}{x}+R^3 N^5+\frac{R^4 N^5}{x^{1/2}}\Bigr)^{1/2}\Bigl(\frac{Q R^4 N^6}{x^2}\Bigr)^{1/2}\\
&\ll x^{3\epsilon}\Bigl(\frac{Q^{1/2} R^3 N^7}{x}+\frac{Q^{1/2} R^4 N^7}{x^{3/2}}+\frac{Q^{1/2}R^{7/2}N^{11/2}}{x}+\frac{Q^{1/2}R^4 N^{11/2}}{x^{5/4}}\Bigr).
\end{align*}
Thus we have $\mathscr{F}_{\ell\ne 0}\ll R^2 N^4/(Q x^{4\epsilon})$ provided we have
\begin{align}
N^6 R^2 Q^{3}&<x^{2-14\epsilon},\\
N^6 R^4 Q^{3}&<x^{3-14\epsilon},\\
N^{3}R^{3}Q^{3}&<x^{2-14\epsilon},\\
N^{3}R^{4}Q^{3}&<x^{5/2-14\epsilon}.
\end{align}
This gives the result.

We can now apply Lemma \ref{lmm:DeshouillersIwaniec} to bound the sum \eqref{eq:FouvryOffDiag}. This gives
\begin{align*}
\mathscr{F}_{\ell\ne 0}& \ll x^\epsilon\Bigl(RT(ST+L)(R+RS)+R^3T\sqrt{(ST+L)S}+R^2LS\Bigr)^{1/2}\|b\|_2\\
&\ll x^{2\epsilon}\Biggl(R N^2\Bigl(N^4+\frac{N^3 R^2}{M}\Bigr)(R+R N^2)\\
&\qquad\qquad\qquad+R^3N^2\sqrt{\Bigl(N^4+\frac{N^3 R^2}{M}\Bigr)N^2}+R^2\frac{N^3 R^2}{M}N^2\Biggr)^{1/2}\|b\|_2.
\end{align*}
Since $MN\asymp x$, this simplifies to
\begin{align}
\mathscr{F}_{\ell\ne0}&\ll x^{2\epsilon} \Bigl(R^2 N^8+\frac{R^4 N^8}{x}+R^3N^5+\frac{R^4 N^5}{x^{1/2}}\Bigr)^{1/2}\|b\|_2. \end{align}

We first consider $\|b\|_2$. We see that
\[
\|b\|_2^2\le \sum_{\ell\sim L}\sum_{s\sim S}\sum_{\substack{t\sim T\\ (s,t)=1}}\Bigl(\sum_{\substack{n_1n_2=t\\ n_1,n_2\sim N}}\sum_{\substack{|k_1|,|k_2|\le K\\ q\sim Q \\ s=(n_1+k_1q)(n_2+k_2q)}}\#\mathcal{C}\Bigr)^2,
\]
where $\mathcal{C}=\mathcal{C}(k_1,k_2,q,n_1,n_2,\ell)$ is the set
\begin{align*}
\mathcal{C}=\{(h_1,h_2)\in [1,H]^2:&\,\ell=a(h_1k_1n_2(n_2+k_2q)-h_2k_2n_1(n_1+k_1q))\}.
\end{align*}
There are at most $\tau(t)=x^{o(1)}$ choices of $n_1,n_2$ given $t$. There are at most $\tau(s)=x^{o(1)}$ choices of $n_1+k_1q$ and $n_1+k_2q$ given $s$. There are then at most $\tau(s-n_1)\tau(s-n_2)=x^{o(1)}$ choices of $k_1,k_2,q$ given $n_1+k_1q$ and $n_2+k_2q$ and $n_1,n_2$. Thus there are at most $x^{o(1)}$ choices of $n_1,n_2,k_1,k_2,q$ given $s$ and $t$. Moreover, since $(s,t)=1$ we have $(n_1,k_1)=(n_2,k_2)=1$. Thus, by Cauchy-Schwarz, we see that
\begin{align*}
\|b\|_2^2&\ll x^{o(1)}\sum_{\ell\sim L}\sum_{s\sim S}\sum_{\substack{t\sim T\\ (s,t)=1}}\sum_{\substack{n_1n_2=t\\ n_1,n_2\sim  N}}\sum_{q\sim Q}\sum_{\substack{|k_1|,|k_2|\le K\\ s=(n_1+k_1q)(n_2+k-2q)}}\#\mathcal{C}^2\\
&\ll x^{o(1)} \mathop{\sum_{n_1,n_2,k_1,k_2,q}\,\,\sum_{h_1,h_2,h_3,h_4}}\limits_{\substack{(h_1-h_3)k_1n_2(n_2+k_2q)=(h_2-h_4)k_2n_1(n_1+k_1q)\\ (n_1,k_1)=(n_2,k_2)=1}}1.
\end{align*}
Here we have suppressed the ranges for the variables in the final line for convenience. We see that if $h_1-h_3=0$, then we must have $h_2-h_4=0$, and so the total contribution from terms with $h_1-h_3=0$ is
\begin{align}
&\ll x^{o(1)} H^2 N^2 K^2Q\ll x^{o(1)} \frac{Q^2 R^4}{M^2}N^2\frac{N^2}{Q^2}Q\ll x^{o(1)} \frac{Q R^4N^6}{x^2}. \end{align}
If instead $h_1-h_3\ne 0$, then we first fix a choice of $h_1$, $h_3$, $n_2$, $k_2$ and $q$, for which there are $O(H^2 N K Q)$ choices. Since $(k_1,n_1)=1$, we have that $n_1(n_1+k_1q)|(h_1-h_3)n_2(n_2+k_2q)$, so there are $O(x^{o(1)})$ choices of $n_1,k_1$. Given such a choice of $n_1,k_1$, we see that $(h_2-h_4)$ is uniquely determined, and so there are $O(H)$ choices of $h_2$ and $h_4$. Thus the total contribution from terms with $h_1-h_3\ne 0$ is 
\begin{equation}
\ll x^{o(1)}H^3 N K Q\ll x^{o(1)} \frac{Q R^4N^6}{x^2}\Bigl(\frac{Q^2R^2}{x N}\Bigr). \end{equation}
But we have $Q^2 R^2<x^{1-8\epsilon}N$ by \eqref{eq:FouvryCond2}, so we find that the bound \eqref{eq:bDiag} is larger than the bound \eqref{eq:bOffDiag}. Thus
\begin{equation}
\|b\|_2^2\ll x^{\epsilon}\frac{Q R^4 N^6}{x^2}. \end{equation}

Putting together \eqref{eq:bBound} and \eqref{eq:FouvryFOffDiag}, we find that
\begin{align*}
\mathscr{F}_{\ell\ne 0}&\ll x^{3\epsilon}\Bigl(R^2 N^8+\frac{R^4 N^8}{x}+R^3 N^5+\frac{R^4 N^5}{x^{1/2}}\Bigr)^{1/2}\Bigl(\frac{Q R^4 N^6}{x^2}\Bigr)^{1/2}\\
&\ll x^{3\epsilon}\Bigl(\frac{Q^{1/2} R^3 N^7}{x}+\frac{Q^{1/2} R^4 N^7}{x^{3/2}}+\frac{Q^{1/2}R^{7/2}N^{11/2}}{x}+\frac{Q^{1/2}R^4 N^{11/2}}{x^{5/4}}\Bigr).
\end{align*}
Thus we have $\mathscr{F}_{\ell\ne 0}\ll R^2 N^4/(Q x^{4\epsilon})$ provided we have
\begin{align}
N^6 R^2 Q^{3}&<x^{2-14\epsilon},\\
N^6 R^4 Q^{3}&<x^{3-14\epsilon},\\
N^{3}R^{3}Q^{3}&<x^{2-14\epsilon},\\
N^{3}R^{4}Q^{3}&<x^{5/2-14\epsilon}.
\end{align}
This gives the result.

We factor $q_2=r d$ where $P^-(r)>z_0\ge P^+(d)$ into parts with large and small prime factors. By putting these in dyadic intervals, we see that it suffices to show for every $A>0$ and every choice of $D R\asymp Q_2$ that
 \begin{align*}
 &\sum_{\substack{q_1\sim Q_1\\ (q_1,a)=1}}\sum_{\substack{r\sim R\\ P^-(d)>z_0\\ (r,a)=1}}\sum_{\substack{d\sim D\\ P^+(d)\le z_0}}|\Delta(q_1 r d)|\ll_{A}\frac{x}{(\log{x})^A}.
 \end{align*}

By Lemma \ref{lmm:RoughModuli} we have the result unless $D\le y_0=x^{1/\log\log{x}}$, and so we may assume that $R=Q_2x^{-o(1)}$. We let $q=q_1d$ and $Q\asymp Q_1D$, and see that it suffices to show
 \begin{align*}
 &\sum_{\substack{q\sim Q\\ (q,a)=1}}\tau(q)\sum_{\substack{r\sim R\\ P^-(d)>z_0\\ (r,a)=1}}|\Delta(q r)|\ll_{A}\frac{x}{(\log{x})^A}.
 \end{align*}

We now see that Lemma \ref{lmm:FouvryEstimate} gives the result provided we have
\begin{align*}
Q\log^{C}{x}&<N,\qquad &N^6 R^2 Q^{3}&<x^{2-14\epsilon},\qquad &N^6 R^4 Q^{3}&<x^{3-14\epsilon},\\
N^{3}R^{3}Q^{3}&<x^{2-14\epsilon},\qquad &N^{3}R^{4}Q^{3}&<x^{5/2-14\epsilon},\qquad
&Q R&<x^{1/2-\epsilon}N^{1/2}.
\end{align*}

We expand the square and swap the order of summation in $\mathscr{D}_3$ to give
\[
\mathscr{D}_3\le \mathscr{D}_4,
\]
where
\begin{align*}
\mathscr{D}_4&:=\sum_{q_2\sim Q}\sum_{\substack{r_2,r_2'\sim R}}\sum_{\substack{n_1,n_1',n_2,n_2'\sim N\\(d n_2n_2',n_1n_1'r_2r_2'q_2)=1}}\sum_{1\le |h|,|h'|\le H}\Bigl|\sum_{\substack{s\\ (s,n_1n_1'q_2r_2r_2')=1}}\psi_0\Bigl(\frac{s}{S}\Bigr)e\Bigl(\frac{a c\overline{d n_2n_2' s}}{n_1n_1'q_2r_2r_2'}\Bigr)\Bigr|,\\
c&=h(n_1-n_2)n_2'r_2'-h'(n_1'-n_2')n_2r_2.
\end{align*}
We have the conditions $(n_1r_2,n_2')=(n_1'r_2',n_2)=1$ from the construction of $\mathcal{N}$. We split $\mathscr{D}_4$ into two subsums depending on whether $c=0$ or not
\begin{equation}
\mathscr{D}_4=\mathscr{D}_{c=0}+\mathscr{D}_{c\ne 0}. \end{equation}

We first consider $\mathscr{D}_{c=0}$. We first make a choice of $h$, $n_2'$, $r_2'$ and $n_1$, for which there are $O(H N^2R)$ choices. Since $(n_1,n_2)=1$ and $c=0$, we see that $n_2|r_2'h n_2'$, so there are at most $x^{o(1)}$ choices of $n_2$. We then see that $r_2 h'(n_1'-n_2')|h(n_1-n_2)n_2'q_2'$, (and this quantity is non-zero), so there are then at most $x^{o(1)}$ choices of $h',n_1',r_2$. Therefore there are 
\[
\ll x^{o(1)} R H N^2\ll x^\epsilon \frac{Q^2 R^3 N^2}{M}
\]
choices of $n_1,n_1,n_2,n_2',h,h',r_2,r_2'$ with $c=0$. Therefore we have
\begin{align}
\mathscr{D}_{c=0}\ll Q S x^\epsilon \frac{Q^2 R^3 N^2}{M} \ll \frac{Q^4 R^4 N^3}{x^{1-\epsilon}}. \end{align}

We now consider $\mathscr{D}_{c\ne 0}$. We apply Lemma \ref{lmm:Weil} to the inner sum, which gives
\begin{equation}
\sum_{(s,n_1n_1'q_1q_2q_2')=1}\psi_0\Bigl(\frac{s}{S}\Bigr)e\Bigl(\frac{a c\overline{d n_2n_2' s}}{n_1n_1'q_2 r_2r_2'}\Bigr)\ll x^{o(1)}Q^{1/2}N R+\frac{x^{o(1)} Q R}{Q R^2 N^2}(c,n_1n_1'q_2r_2r_2'). \end{equation}
The first term in \eqref{eq:SmallFactorWeil} contributes
\begin{align}
&\ll x^{o(1)}\sum_{n_1,n_1',n_2,n_2'\ll N}\sum_{q_2\ll Q}\sum_{r_2,r_2'\ll R}\sum_{|h|,|h'|\ll H}Q^{1/2} N R\nonumber \\
&\ll x^{o(1)} N^5 Q^{3/2} R^3 H^2\nonumber\\
&\ll \frac{N^7 Q^{11/2}R^7}{x^{2-\epsilon}} \end{align}
to $\mathscr{D}_{c\ne 0}$. We now consider the second term of  \eqref{eq:SmallFactorWeil}. We note that if $e=(c,n_2)$ then since $(n_2,n_1n_1'r_2r_2')=1$ we must have that $e|h' n_2'$ so $(c,n_2)\le (n_2,h n_2')$. Thus
\[
(c,n_1n_1'n_2n_2'q_2r_2r_2')\le (c,q_2)(c,n_2)(c,n_1n_1'n_2'r_2r_2')\le (c,q_2)(n_2,h n_2')N^3R^2.
\]
Thus the second term in \eqref{eq:SmallFactorWeil} contributes
\begin{align*}
&\ll x^{o(1)}\sum_{n_1,n_1',n_2'\ll N}\sum_{r_2,r_2'\ll R}\sum_{|h|,|h'|\ll H}\frac{N^3 R^2}{R N^2}\sum_{n_2\ll N}(n_2,h n_2')\sum_{q_2\ll Q}(c,q_2)\\
&\ll  x^{o(1)}\sum_{n_1,n_1',n_2'\ll N}\sum_{r_2,r_2'\ll R}\sum_{|h|,|h'|\ll H}NR\cdot x^{o(1)}N\cdot x^{o(1)}Q\\
&\ll x^{o(1)}N^5 Q R^3 H^2
\end{align*}
to $\mathscr{D}_{c\ne 0}$, which is smaller that the bound \eqref{eq:DOffDiagDiag}. Thus
\begin{equation}
\mathscr{D}_{c\ne 0}\ll  \frac{N^7 Q^{11/2}R^7}{x^{2-\epsilon}}. \end{equation}

We factor $q_1=d_1 q$ and $q_2=d_2 r$ where $P^-(r),P^-(q)>z_0\ge P^+(d_1),P^+(d_2)$ into parts with large and small prime factors. By putting these in dyadic intervals, we see that it suffices to show for every $A>0$ and every choice of $D_1 Q\asymp Q_1$ and $D_2 R\asymp Q_2$ that
 \begin{align*}
 &\sum_{\substack{d_1\sim D_1\\ P^+(d)\le z_0}}\sum_{\substack{d_2\sim D_2\\ P^+(d)\le z_0}}\sum_{\substack{q\sim Q\\ P^-(q)>z_0 \\ (q_1,a)=1}}\sum_{\substack{r\sim R\\ P^-(r)>z_0\\ (r,a)=1}}|\Delta(q r d_1 d_2)|\ll_{A}\frac{x}{(\log{x})^A}.
 \end{align*}

We now see that Lemma \ref{lmm:SmallDivisorExponential} gives the result provided we have
\begin{align*}
N^6 Q^{7} R^8&<x^{4-12\epsilon},\\
Q^2 R&<x^{1-6\epsilon} N.
\end{align*}
Recalling that $Q=Q_1x^{o(1)}$, and $R=Q_2x^{-o(1)}$ then gives the result.

We assume throughout that $H\ll QR^2N/x^{1-\epsilon}$ and that $Q\ll N$, and deduce the other conditions are sufficient to give the result. Since we only consider $r_1,r_2$ with $P^-(r_1r_2)\ge z_0$, $r_1$ and $r_2$ have at most $(\log\log{x})^3$ prime factors. Therefore, by Lemma ef{lmm:FouvryDecomposition}, there are $O(\exp(\log\log{x})^5))$ different sets $\mathcal{N}_1,\mathcal{N}_2,\dots$ which cover all possible pairs $(r_1,r_2)$, and such that if $(r_1,r_2),(r_1',r_2')\in\mathcal{N}_j$ then $\gcd(r_1,r_2')=\gcd(r_1',r_2)=1$. Taking the worst such set $\mathcal{N}$, we see that  egin{align*} \mathscr{Z}&\ll \exp((\log\log{x})^5)\Bigl|\sum_{\substack{q\sim Q\ (q,a)=1}}\sum_{\substack{r_1,r_2\sim R\ (r_1,a r_2)=1\ (r_2,a q r_1)=1\ (r_1,r_2)\in\mathcal{N}}}\sum_{\substack{n_1,n_2\sim N\ n_1\equiv n_2\Mod{q}\ (n_1,q r_ 1 n_2)=1\ (n_2,q r_2 n_1)=1\ |n_1-n_2|\ge N/(\log{x})^C}} rac{\alpha_{n_1}\overline{\alpha_{n_2}}c_{q,r_1}\overline{c_{q,r_2}}}{q r_1 r_2}\ &\qquad\qquad	imes\sum_{1\le |h|\le H}\hat{\psi_0}\Bigl( rac{h M}{q r_1 r_2}\Bigr)e\Bigl(ah\Bigl( rac{\overline{n_1 r_2}}{qr_1}+ rac{\overline{n_2 q r_1}}{r_2}\Bigr)\Bigr)\Bigr|. \end{align*} We now Cauchy in $n_1,n_2$ and $q$ to eliminate the $\alpha$-coefficients and insert a smooth majorant for the $n_1$ and $n_2$ summations. This gives (using $Q\ll N$) \[ \mathscr{Z}^2\ll \exp(2(\log\log{x})^5)\Bigl(\sum_{q\sim Q}\sum_{\substack{n_1,n_2\sim N\ n_1\equiv n_2\Mod{q}}} rac{1}{q^2}\Bigr)|\mathscr{Z}_2|\ll  rac{x^\epsilon N^2}{Q^2}|\mathscr{Z}_2|, \] where  egin{align*} \mathscr{Z}_2&:=\sum_{\substack{q\sim Q\ (q,a)=1}}\sum_{\substack{n_1,n_2\ (n_1n_2,q)=1}}\psi_0\Bigl( rac{n_1}{N}\Bigr)\psi_0\Bigl( rac{n_2}{N}\Bigr)\ &\qquad 	imes\Bigl|\sum_{\substack{r_1,r_2\sim R\ (r_1,a r_2 n_1)=1\ (r_2,a q r_1 n_2)=1\ (r_1,r_2)\in\mathcal{N}}} rac{c_{q,r_1}\overline{c_{q,r_2}}}{r_1 r_2}\sum_{1\le |h|\le H}\hat{\psi_0}\Bigl( rac{h M}{q r_1 r_2}\Bigr)e\Bigl(ah\Bigl( rac{\overline{n_1 r_2}}{q r_1}+ rac{\overline{ n_2q r_1}}{r_2}\Bigr)\Bigr)\Bigr|^2\ &\le  rac{1}{R^4}|\mathscr{Z}_3|, \end{align*} where  egin{align*} \mathscr{Z}_3:=\sum_{q\sim Q}\sum_{\substack{r_1,r_1',r_2,r_2'\sim R\ (qr_1r_1',r_2r_2')=1}}\sum_{1\le |h|,|h'|\le H}\Bigl|\sum_{\substack{n_1,n_2\ n_1\equiv n_2\Mod{q} \ (n_1,qr_1r_1')=1\ (n_2,r_2r_2')=1}}\psi_0\Bigl( rac{n_1}{N}\Bigr)\psi_0\Bigl( rac{n_2}{N}\Bigr)e\Bigl( rac{c_1\overline{n_1}}{q r_1r_1'}+ rac{c_2\overline{n_2}}{r_2 r_2'}\Bigr)\Bigr|, \end{align*} and where $c_1\Mod{q r_1r_1'}$ and $c_2\Mod{r_2r_2'}$ are given by  egin{align*} c_1&=a(h r_1'r_2'-h' r_1r_2)\overline{r_2r_2'},\ c_2&=a (h r_1'r_2'-h' r_1r_2)\overline{q r_1r_1'}. \end{align*} (Here we used the fact that $(r_1,r_2),(r_1',r_2')\in\mathcal{N}$ to conclude $(r_1,r_2')=(r_1',r_2)=1$.) In order to establish the desired bound $\mathscr{Z}\ll N^2/(x^\epsilon Q)$, it suffices to show $\mathscr{Z}_2\ll N^2/x^{3\epsilon}$, and so it suffices to prove  egin{equation} \mathscr{Z}_3\ll  rac{N^2 R^4}{x^{3\epsilon}}. \end{equation} We separate the diagonal terms $\mathscr{Z}_{=}$ with $hr_1'r_2'=h'r_1r_2$ and the off-diagonal terms $\mathscr{Z}_{
e}$ with $h r_1'r_2'
