We note that $f_0$ is supported on $[1/10,10]$, $f_0\ge 1$ on $[1,2]$ and $\|f_0^{(j)}\|_\infty\ll_j 1$ for all $j\ge 1$. We then expand out the square, giving
\begin{align*}
\mathscr{B}'&\le \sum_{c}f_0\Bigl(\frac{c}{C}\Bigr)\sum_{\substack{d\\ (c,d)=1}}f_0\Bigl(\frac{d}{D}\Bigr)\sum_{\substack{k\sim K \\ (k,c)=1}}k\Biggl|\sum_{\substack{e\sim E\\ (e,ck)=1}}\sum_{ h\sim H}\sum_{\substack{ n\sim N\\ d n\equiv c\Mod{k e}\\ (n,c)=1}}\beta(h,e,n)e\Bigl(\frac{a h k e \overline{d n}}{c}\Bigr)\Biggr|^2\\
&=\sum_{k\sim K}k\sum_{\substack{e_1,e_2\sim E\\ (e_1e_2,k)=1}}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{k}\\ (n_1,ke_1)=1\\ (n_2,ke_2)=1}}\sum_{h_1,h_2\sim H}\beta(h_1,e_1,n_1)\overline{\beta(h_2,e_2,n_2)}\\
& \times \sum_{\substack{c\\ (c,e_1e_2n_1n_2k)=1}}f_0\Bigl(\frac{c}{C}\Bigr)\sum_{\substack{d\\ d\equiv c\overline{n_1}\Mod{ke_1}\\ d\equiv c\overline{n_2} \Mod{ke_2}}}f_0\Bigl(\frac{d}{D}\Bigr)e\Bigl(\frac{ak(h_1e_1n_2-h_2e_2n_1)\overline{n_1n_2d}}{c}\Bigr).
\end{align*}

Let $e_0=(e_1,e_2)$ and $e_1=e_0e_1'$, $e_2=e_0e_2'$ for some $e_1',e_2',e_0$ which we may assume to be pairwise coprime since $\beta(h,e,n)$ is supported on square-free $e$. We see that the inner sum is 0 unless $n_1\equiv n_2\Mod{e_0}$. Putting $e_0$ into dyadic ranges, we see that
\begin{align*}
\mathscr{B}'_2&\ll \log{x}\sup_{\substack{E_0\le E}}\Bigl|\sum_{\substack{k\sim K}}k\sum_{\substack{e_0\sim E_0\\ (e_0,k)=1}}\sum_{\substack{e_1',e_2'\sim E/e_0\\ (e_1' e_2',e_0k)=1\\ (e_1',e_2')=1}}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{k e_0}\\ (n_1 n_2,k e_0)=1\\ (n_1,e_1')=(n_2,e_2')=1}}\\
&\qquad\times\sum_{\substack{h_1,h_2\sim H\\ h_1e_1'n_2\ne h_2e_2'n_1}}\beta(h_1,e_0 e_1',n_1)\overline{\beta(h_2,e_0 e_2',n_2)}\sum_{\substack{c\\ (c,e_0e_1'e_2' k n_1n_2)=1}}f_0\Bigl(\frac{c}{C}\Bigr)\\
&\qquad \times \sum_{\substack{d\\ d\equiv c\overline{n_1}\Mod{k e_0 e_1'}\\ d\equiv c\overline{n_2} \Mod{k e_0 e_2'}}}f_0\Bigl(\frac{d}{D}\Bigr)e\Bigl(\frac{a k e_0(h_1 e_1' n_2 - h_2 e_2' n_1)\overline{n_1 n_2 d}}{c}\Bigr)\Bigr|.
\end{align*}

By Lemma \ref{lmm:InverseCompletion} we have that
\begin{align*}
&\sum_{\substack{d\\ d\equiv c\overline{n_1}\Mod{k e_0e_1'}\\ d\equiv c\overline{n_2} \Mod{e_2'}}}f_0\Bigl(\frac{d}{D}\Bigr)e\Bigl(\frac{a k e_0(h_1e_1'n_2-h_2e_2'n_1)\overline{n_1n_2d}}{c}\Bigr)=\frac{\hat{f_0}(0)D}{c k e_0 e_1' e_2'}\sum_{\substack{b\Mod{d}\\ (b,d)=1}}e\Bigl(\frac{r b}{c}\Bigr)\\
&\qquad\qquad+\frac{D}{c k e_0e_1'e_2'}\sum_{0<|\ell|<L_0}\hat{f_0}\Bigl(\frac{\ell D}{c k e_0 e_1' e_2'}\Bigr)e\Bigl(\frac{\ell\mu}{k e_0e_1'e_2'}\Bigr)S(r,\ell;c)+O(x^{-100}),
\end{align*}
where $r=r(h_1,h_2,e_1',e_2',n_1,n_2)$ and $L_0$ are given by
\begin{align*}
r&:=a (h_1e_1'n_2-h_2e_2'n_1)\overline{n_1n_2e_1'e_2'},\\
L_0&:=\frac{C E^2 K}{D E_0}\log^5{x},
\end{align*}
and $\mu=\mu(n_1,n_2,k,e_0,e_1',e_2')$ is the solution $\Mod{ke_0e_1'e_2'}$ of the congruences
\begin{align*}
\mu&\equiv \overline{n_1}\Mod{ke_0e_1'},\\
\mu&\equiv \overline{n_2}\Mod{ke_0e_2'}.
\end{align*}
(There is a unique solution by the Chinese Remainder Theorem since $n_1\equiv n_2\Mod{ke_0}$ and $(e_1',e_2')=1$.) We note that $\mu$ does not depend on $c$ or $\ell$. Substituting this into $\mathscr{B}_2'$, we find that
\[
\mathscr{B}_2'\le \log{x}\sup_{E_0\le E}(\mathscr{B}_3'+\mathscr{B}_4')+O(x^{-90}),
\]
where $\mathscr{B}_3'$ is the contribution from the first term involving $\hat{f}_0(0)$ term, and $\mathscr{B}_4'$ is the contribution from the sum over $\ell$, given explicitly by
\begin{align*}
\mathscr{B}_4'&:=
\sum_{\substack{k\sim K}}k\sum_{\substack{e_0\sim E_0\\ (e_0,k)=1}}\sum_{\substack{e_1',e_2'\sim E/e_0\\ (e_0k,e_1'e_2')=1\\(e_1',e_2')=1}}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{k e_0}\\ (n_1n_2, k e_0)=1\\ (n_1,e_1')=1=(n_2,e_2')}}\sum_{\substack{h_1,h_2\sim H\\ h_1e_1'n_2\ne h_2e_2'n_1}}\\
&\qquad\times\beta(h_1,e_0e_1',n_1)\overline{\beta(h_2,e_0e_2',n_2)}\sum_{\substack{c\\ (c,e_0 e_1'e_2' k n_1n_2)=1}}f_0\Bigl(\frac{c}{C}\Bigr)\frac{D}{c k e_0e_1'e_2'}\\
&\qquad\times\sum_{0<\ell<L_0}\hat{f_0}\Bigl(\frac{\ell D}{c k e_0e_1'e_2'}\Bigr)e\Bigl(\frac{\ell\mu}{k e_0e_1'e_2'}\Bigr)S(r,\ell;c').
\end{align*}

Since $H\ll EN$ by assumption, we see that $C^2E^2N^2\gg C^2EHN$ and $C^3E^2K/D\gg C^3EHK/(DN)$, so the first term is larger than the third term and the fourth term is larger than the final term in the final set of parentheses. Thus we may drop the third and final term in the final set of parentheses. Similarly, the $(1+H/(EN))$ factors are $O(1)$ and so can be dropped. Thus, simplifying the terms slightly we find that
\begin{align*}
\frac{D E_0}{ C E^2}\mathscr{B}_2''&\ll  x^{o(1)}E^2 H K^{1/2} N^{2} \Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}\Bigl( C D N^2+E H K N+C^2K\Bigr)^{1/2}.
\end{align*}
This gives the result.

First we recall that
\begin{align*}
\mathscr{B}''_=&:=\sum_{\substack{s_1\sim S_1\\ s_2\sim S_2}}\sum_{\substack{k'\sim K/s_2}} \sum_{\substack{e_0'\sim E_0/s_1}}\sum_{\substack{e_1',e_2'\sim E/e_0\\ (e_1',e_2')=1}}\sum_{\substack{n\sim N}}\\
&\times\sup_{\theta\in\mathbb{R}}\Bigl|\sum_{\substack{h_1,h_2\sim H}}\xi_{h_1,h_2}\sum_{\substack{c'\\ (c',n e_1'e_2')=1}}\sum_{\ell}g_{0}\Bigl(\frac{c'}{C/(S_1S_2)}\Bigr)e(\ell \theta)S(m\overline{r},\ell;c's_1s_2)\Bigr|,
\end{align*}
for some 1-bounded coefficients $\xi_{h_1,h_2}$ (also depending on $s_1,s_2,k',e_0',e_1',e_2',n$) and where
\begin{align*}
m=a(h_1e_1'-h_2e_2'),\qquad 
r=n e_1'e_2'.
\end{align*}

By Lemma \ref{lmm:DeshouillersIwaniec2} and Lemma \ref{lmm:KimSarnak} we have
\begin{align*}
&\sum_{m\sim M}b_m'\sum_{\ell\sim L}e(\ell\theta)\sum_{(c',n e_1'e_2')=1}g_{0}\Bigl(\frac{c'}{C/(S_1S_2)}\Bigr)S(m\overline{r},\ell;c's_1s_2)\\
&\ll x^{o(1)} L^{1/2}\Bigl(1+\frac{C^2 R}{L M}\Bigr)^{7/64}\Bigl(C^2 R+L M+\frac{C^2 (M+L)}{S_1 S_2}+\frac{C^2 L M}{R S_1 S_2}\Bigr)^{1/2}\|b_m'\|.
\end{align*}

We have that
\begin{align*}
\sum_{\substack{s_1\sim S_1}}\sum_{s_2\sim S_2}&\sum_{\substack{k'\sim K/s_2}} \sum_{\substack{e_0'\sim E_0/s_1}}\sum_{\substack{e_1',e_2'\sim E/e_0\\ (e_1',e_2')=1}}\sum_{\substack{n\sim N}}\|b_m'\|^2\\
&\ll x^{o(1)} K E_0 N \sum_{m\sim M}\sum_{h_1\sim H}\sum_{e_1'\ll E/E_0}\sum_{\substack{e_2'\ll E/E_0\\ (e_1',e_2')=1\\ e_2|m+ah_1e_1'}}\\
&\qquad\times\sum_{\substack{h_2\sim H\\ ah_2e_2'=m+ah_1e_1'}}\sum_{\substack{h_1'\sim H\\ a h_1'\equiv m\overline{e_1'}\Mod{e_2'}}}\sum_{\substack{h_2'\sim H\\ ah_2'e_2'=m+ah_1'e_1'}}1\\
&\ll x^{o(1)} E H K M N\Bigl(1+\frac{E_0 H}{E}\Bigr).
\end{align*}
Thus we find that
\begin{align*}
\mathscr{B}_{=}''&\ll \sup_{\substack{M\ll E H/E_0 \\ L\ll x^{o(1)}C E^2 K/(DE_0) \\ 1\ll S_1S_2\ll E_0 K\\ R\asymp E^2 N/E_0^2}}x^{o(1)} \Bigl(E H K M N\Bigr)^{1/2}\Bigl(1+\frac{E_0 H}{E}\Bigr)^{1/2}\Bigl(\frac{E^2 K N}{E_0}\Bigr)^{1/2} \\
&\qquad \times \Bigl(1+\frac{C^2 R }{L M}\Bigr)^{7/64}(L^{1/2})\Bigl(RC^2+L M+\frac{C^2(M+L)}{S_1S_2}+\frac{C^2 ML}{RS_1S_2}\Bigr)^{1/2}.
\end{align*}
The maximum of the expression above clearly occurs when $M$ and $L$ take their largest values and when $S_1,S_2$ take their smallest values.

After removing a factor $1/E_0$, we see that the expression is maximized when $E_0=1$. Thus we find that
\begin{align*}
\mathscr{B}_{=}''&\ll \frac{x^{o(1)}}{E_0}\Bigl(E^2 H^2 K N\Bigr)^{1/2}\Bigl(1+\frac{H}{E}\Bigr)^{1/2}\Bigl(E^2 K N\Bigr)^{1/2} \Bigl(\frac{C E^2 K}{D}\Bigr)^{1/2}\Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}\\
&\qquad \times \Bigl(C^2 E^2 N+ \frac{C E^3 H K}{D}+C^2 E H+\frac{C^3 E^2 K}{D}+\frac{C^3 E H K}{D N}\Bigr)^{1/2}.
\end{align*}

Again, since $H\ll EN$ by assumption, we see that in the final set of parentheses the first term is larger than the third and the fourth term is larger than the final term. Thus, we obtain
\begin{align*}
\mathscr{B}_{=}''&\ll x^{o(1)}\frac{C E^2 }{D E_0}\Bigl(E^4 H^2 K^3 N^2\Bigr)^{1/2}\Bigl(1+\frac{H}{E}\Bigr)^{1/2}\Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}\\
&\qquad \times\Bigl(C D N+ E H K+C^2 K\Bigr)^{1/2}.
\end{align*}
This gives the result.

Applying Lemmas \ref{lmm:BFI1}, \ref{lmm:BFI2} and \ref{lmm:BFI3} in turn gives
\begin{align*}
\mathscr{B}'&\ll (C D H K N + C E H K^2 N+D H^2 N^2+D H^2 K N)\log^{O(1)}{x}\\
&+ x^\epsilon\Bigl(E^{4} H^2 K N^{4}\Bigr)^{1/2}\Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}\Bigl(C D N^2+ E H K N+C^2 K\Bigr)^{1/2} \\
&+x^\epsilon\Bigl(E^4 H^2 K^3 N^2\Bigr)^{1/2}\Bigl(1+\frac{H}{E}\Bigr)^{1/2}\Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}\Bigl(C D N+ E H K+C^2 K\Bigr)^{1/2}.
\end{align*}

Similarly
\begin{align*}
&\Bigl(E^{4} H^2 K N^{4}\Bigr)^{1/2}\Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}\Bigl(C^2 K\Bigr)^{1/2} \\
& \qquad+\Bigl(E^4 H^2 K^3 N^2\Bigr)^{1/2}\Bigl(1+\frac{H}{E}\Bigr)^{1/2} \Bigl(1+\frac{CD N}{E H K}\Bigr)^{7/64}
\Bigl(C^2 K\Bigr)^{1/2}\\
&=(E N^2 + H K^2+EK^2)^{1/2}\Bigl(C^2 E^3 H^2 K^2 N^2\Bigr)^{1/2}\Bigl(1+\frac{C D N}{E H K}\Bigr)^{7/64}.
\end{align*}
Thus the result holds.

This simplifies to give
\begin{align*}
\mathscr{B}'&\ll x^{o(1)}\Bigl(\frac{K^4 L^4}{E x} +\frac{K^4 L^5}{E Q x}+\frac{K^3 L^4 Q^2}{x^2}+\frac{K^4 L^4 Q}{E x^2}\Bigr)\\
&\quad+x^\epsilon \Bigl(\frac{K^2 L^2}{E Q^2}+E L^3+\frac{K^3 L^3}{E^2 Q x}\Bigr)^{1/2}\Bigl( \frac{E^2 K^3 L^5 Q}{x^2} \Bigr)^{1/2}x^{7/64}\Bigl( K^2 L^2 \Bigr)^{1/2} \\
&\quad+x^\epsilon \Bigl(\frac{K^2 L^2}{E Q^2} +E L^2+ \frac{K^3 L^3}{E^2 Q x}\Bigr)^{1/2}\Bigl( \frac{E K^6 L^8}{x^2}\Bigr)^{1/2}x^{7/64}.
\end{align*}

We recall that $x^{1/2-\epsilon/2}<Q$, and $E Q<x^\epsilon K L<x$ so that $x>K L$, $x>Q E$ and $K^3L^3/(E^2 Q x)>K^2L^2/(E Q^2)$. Moreover, the conditions on the proposition imply that $L,K<x^{1/2-\epsilon/2}<Q$, and so $K,L>L K /Q$ and $EL^3> L^3 K^3/(E^2 Q x)$. Thus
\begin{align*}
\mathscr{B}'&\ll x^{o(1)}\Bigl(\frac{K^4 L^4}{E x} +\frac{Q^2 K^3 L^4}{x^2}\Bigr)+x^\epsilon \Bigl(E L^3\Bigr)^{1/2}\Bigl( \frac{Q K^3 L^5 E^2}{x^2} \Bigr)^{1/2}x^{7/64}\Bigl( K^2 L^2 \Bigr)^{1/2} \\
&\quad+x^\epsilon \Bigl(E L^2+ \frac{K^3 L^3}{E^2 Q x}\Bigr)^{1/2}\Bigl( \frac{E K^6 L^8}{ x^2}\Bigr)^{1/2}x^{7/64}.
\end{align*}

If this holds, we then have
\begin{align*}
\frac{\mathscr{B}'}{K^2L^3} &\ll x^{o(1)}\Bigl(\frac{1}{x^\epsilon} +\frac{Q^2 K L}{x^2}\Bigr)+x^{3\epsilon} \Bigl( \frac{Q K^{7} L^{7} }{x^5}+
\frac{Q K L^{4} }{x^2} \Bigr)^{1/2}x^{7/64}\\
&\quad +x^{3\epsilon}\Bigl(\frac{K^2 L^4}{x^2}+\frac{K^6 L^{6} }{x^4}+\min\Bigl(\frac{K^5 L^{5} }{Q x^3}, \frac{K^3 L^4 }{Q x^2}\Bigr)\Bigr)^{1/2}x^{7/64}\\
&\ll x^{\epsilon/2}\Bigl(\frac{1}{x^\epsilon} +\frac{Q^2 K L}{x^2}\Bigr)+x^{3\epsilon} \Bigl( \frac{Q^{32} K^{224} L^{224} }{x^{153} }+\frac{Q^{32}K^{32}L^{128}}{x^{57}}\Bigr)^{1/64}\\
&\quad +x^{3\epsilon}\Bigl(\frac{K^{64} L^{128}}{x^{57}}+\frac{K^{192} L^{192}}{x^{121}}+\frac{K^{160} L^{160} }{Q^{32} x^{89}} \Bigr)^{1/64}.
\end{align*}
This shows that $\mathscr{B}'\ll K^2 L^3 x^{-\epsilon/2}$ provided we have
\begin{align}
K L&<\min\Bigl(\frac{ x^{2-2\epsilon}}{Q^2},\frac{x^{153/224-2\epsilon}}{Q^{1/7}},x^{121/192-2\epsilon},x^{89/160-2\epsilon}Q^{1/5}\Bigr), \\
KL^2&<x^{57/64-4\epsilon}, \\
KL^4&<\frac{x^{57/32-7\epsilon}}{Q}. \end{align}

Since $KL>Q(\log{x})^C$ by assumption, we have that $N>KL>Q(\log{x})^C$. The conditions of the proposition ensure that
\begin{align}
N\ll KL \ll  \frac{x^{153/224}}{Q^{1/7}} \ll x^{5/8}, \end{align}
and so $M\gg x/N \gg x^\epsilon$. Thus, by Proposition \ref{prpstn:GeneralDispersion}, it suffices to show that for a suitable choice of $E\in [1,KL(\log{x})^{-C_1}/Q]$ we have
\[
\mathscr{E}_1,\mathscr{E}_2\ll_{A} \frac{N^2}{Q (\log{x})^{C_1}},
\]
where $C_1=C_1(A)$ is a constant depending only on $A$, $H=Q(\log{x})^5/M$, and $\mathscr{E}_{1}$ is given by
\begin{align*}
\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\\ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\frac{1 }{\phi(q e)q}\sum_{\substack{n_1,n_2\sim N\\ (n_1n_2,q e)=1}}\alpha_{n_1}\overline{\alpha_{n_2}}\sum_{1\le |h|\le H_1}\hat{\psi}_0\Bigl(\frac{-h M}{q}\Bigr)e\Bigl( \frac{a h \overline{ n_1}}{q}\Bigr),
\end{align*}
and $\mathscr{E}_2$ is given by
\begin{align*}
\sum_{e\sim E}\mu^2(e)\sum_{\substack{q\\ (q,a)=1}}\psi_0\Bigl(\frac{q}{Q}\Bigr)\frac{1}{q}\sum_{\substack{n_1,n_2\sim N\\ n_1\equiv n_2\Mod{q e}\\ (n_1n_2,eq)=1\\(n_2,n_1)=1\\ |n_1-n_2|\ge N/(\log{x})^C}}\alpha_{n_1}\overline{\alpha_{n_2}}\sum_{1\le |h|\le H_2}\hat{\psi}_0\Bigl(\frac{-h M}{q}\Bigr)e\Bigl(\frac{ah\overline{n_1}}{q}\Bigr).
\end{align*}

Define $J:=\lceil(\log{x})^C+1\rceil$ and
\[
\widetilde{\psi}_i(t):=\begin{cases}
\psi_0((t-1)(\log{x})^C-i+2),&1+\frac{i-3/2}{(\log{x})^C}\le t\le 1+\frac{i-1}{(\log{x})^C},\\
1,&1+\frac{i-1}{(\log{x})^C}\le t \le 1+\frac{i-1/2}{(\log{x})^C},\\
1-\psi_0((t-1)(\log{x})^C-i+1),&1+\frac{i-1/2}{(\log{x})^C}\le t\le 1+\frac{i}{(\log{x})^C},\\
0,&\text{otherwise.}
\end{cases}
\]
Then it is easy to verify that $\widetilde{\psi}_i(t)$ is smooth, non-negative, satisfies $\|\widetilde{\psi}_i^{(j)}\|_\infty\ll ((j+1)\log{x})^{j C}$ and that $\sum_{j=1}^J\widetilde{\psi_j}$ satisfies the bounds of the lemma.

We first note that by Lemma \ref{lmm:FundamentalLemma}
\begin{align*}
\sum_{\substack{n\in\mathcal{I}\\ P^-(n)>z}}&\Bigl(\mathbf{1}_{m n\equiv a\Mod{q}}-\frac{\mathbf{1}_{(m n,q)=1}}{\phi(q)}\Bigr)\\
&\le \sum_{\substack{n\in\mathcal{I}}}\Bigl(\sum_{d|n}\lambda^+_d\Bigr) \mathbf{1}_{m n\equiv a\Mod{q}}-\sum_{\substack{n\in\mathcal{I}}}\Bigl(\sum_{d|n}\lambda^-_d\Bigr) \frac{\mathbf{1}_{(m n,q)=1}}{\phi(q)}\\
&= \sum_{d\le y_0}\lambda^+_d \sum_{\substack{d n'\in\mathcal{I}}}\Bigl(\mathbf{1}_{m d n'\equiv a\Mod{q}}-\frac{\mathbf{1}_{(m d n',q)=1}}{\phi(q)}\Bigr)\\
&\qquad +O\Bigl(\Bigl| \sum_{d\le y_0}(\lambda^+_d-\lambda^-_d) \sum_{\substack{d n'\in\mathcal{I}}}\frac{\mathbf{1}_{(m d n',q)=1}}{\phi(q)}\Bigr)\Bigr|\Bigr),
\end{align*}
and similarly we obtain a lower bound with the roles of $\lambda^+_d$ and $\lambda^-_d$ reversed.

By Lemma \ref{lmm:FundamentalLemma} (and recalling that $MN\asymp x$, $N\ge x^\epsilon$), the final term above contributes
\begin{align*}
&\ll \sum_{q\sim Q}\frac{1}{\phi(q)}\sum_{m\sim M}\Bigl|\sum_{\substack{d\le y_0\\ (d,q)=1}} (\lambda^+_d-\lambda_d^-)\Bigl(\frac{\#\mathcal{I}\phi(q)}{d q}+O(\tau(q))\Bigr)\Bigr|\\
&\ll \frac{MN}{(\log{x})^{\log\log{x}}}+M x^{o(1)}\ll_B \frac{x}{(\log{x})^B}.
\end{align*}

We now split the summation over $d$ into one of $O(\log{x})^{10 B+1}$ subsums of the form $d\in [(1+\eta)^k,(1+\eta)^{k+1})$ where $\eta:=(\log{x})^{-10 B}$. Taking the worst subsum and the worst value of $j\ll (\log{x})^{2B}$, it suffices to show that
\begin{align*}
\sum_{q\sim Q}c_q \sum_{m\sim M}\alpha_m\sum_{\substack{d\in [d_0,d_0(1+\eta))\\ d\le y_0}}\lambda^+_d \sum_{\substack{n'}}\widetilde{\psi}_j\Bigl(\frac{n' d}{N}\Bigr)\Bigl(\mathbf{1}_{m d n'\equiv a\Mod{q}}-\frac{\mathbf{1}_{(m d n',q)=1}}{\phi(q)}\Bigr)\\
\ll_B \frac{x}{(\log{x})^{13 B}},
\end{align*}

We let
\begin{equation}
F(h_1,h_2,h_3;a,q)=\sum_{\substack{b_1,b_2,b_3\in(\mathbb{Z}/q\mathbb{Z})^\times \\ b_1b_2b_3=a}}e\Bigl(\frac{h_1b_1+h_2b_2+h_3b_3}{q}\Bigr) \end{equation}
be a closely related sum.

This essentially follows from completing the sums in $n_1,n_2,n_3$. We wish to estimate $\mathscr{K}=\mathscr{K}_1-\mathscr{K}_2$, where
\begin{align*}
\mathscr{K}_1&:=\sum_{\substack{q\sim Q}}\frac{c_q}{\phi(q d)}\sum_{m\sim M}\alpha_m\sum_{\substack{n_1,n_2,n_3\\ (m n_1n_2n_3,q d)=1}}\psi_1\Bigl(\frac{n_1}{N_1}\Bigr)\psi_2\Bigl(\frac{n_2}{N_2}\Bigr)\psi_3\Bigl(\frac{n_3}{N_3}\Bigr),\\
\mathscr{K}_2&:=\sum_{\substack{q\sim Q}}c_{q}\sum_{m\sim M}\alpha_m\sum_{\substack{n_1,n_2,n_3\\ m n_1n_2n_3\equiv a\Mod{q d}}}\psi_1\Bigl(\frac{n_1}{N_1}\Bigr)\psi_2\Bigl(\frac{n_2}{N_2}\Bigr)\psi_3\Bigl(\frac{n_3}{N_3}\Bigr).
\end{align*}

Thus we are left to consider the contribution from the middle term sum over $1\le |h_1|\le H_1$. Lemma \ref{lmm:InverseCompletion} shows that for $H_2:=Q D x^\epsilon/N_2$
\begin{align*}
\sum_{(n_2,q d)=1}\psi_2&\Bigl(\frac{n_2}{N_2}\Bigr)e\Bigl(\frac{b\overline{n_2}}{q d}\Bigr)=\frac{N_2\hat{\psi_2}(0)}{q d}\sum_{(b_2,q d)=1}e\Bigl(\frac{b b_2}{q d}\Bigr)\\
&+\frac{N}{q d}\sum_{1\le |h_2|\ll H_2}\hat{\psi_2}\Bigl(\frac{h_2 N_2}{q d}\Bigr)\sum_{\substack{b_2\Mod{q d}\\ (b_2,q d)=1}} e\Bigl(\frac{b\overline{b_2}+h_2 b_2}{q d}\Bigr)+O_C(x^{-10}).
\end{align*}
The first term above is a multiple of a Ramanujan sum, and so $\ll N_2\gcd(b,q d)/q d$. We apply this with $b=ah_1\overline{m n_3}$ to evaluate the $n_2$ sum, and then similarly to evaluate the $n_3$ sum. This gives with $H_3:=Q D x^\epsilon/N_3$ 
\begin{align*}
&\sum_{\substack{n_2,n_3\\ (n_2n_3,q d)=1}}\psi_2\Bigl(\frac{n_2}{N_2}\Bigr)\psi_3\Bigl(\frac{n_3}{N_3}\Bigr)e\Bigl(\frac{ah_1\overline{m n_2n_3}}{q d}\Bigr)\\
&=\frac{N_2N_3}{q^2 d^2}\sum_{\substack{1\le |h_2|\le H_2\\ 1\le |h_3|\le H_3}}\hat{\psi_2}\Bigl(\frac{h_2 N_2}{q d}\Bigr)\hat{\psi_3}\Bigl(\frac{h_3 N_3}{q d}\Bigr)\sum_{b_2,b_3\in(\mathbb{Z}/q d\mathbb{Z})^\times }e\Bigl(\frac{a\overline{b_2 b_3 m}+h_2 b_2+h_3 b_3}{q d}\Bigr)\\
&\qquad+O_C\Bigl(\frac{N_2N_3}{Q D}(h_1,q d)\Bigr).
\end{align*}

Putting this all together, we obtain
\begin{align*}
\mathscr{K}_2&=\mathscr{K}_{MT}+\frac{N_1N_2N_3}{Q^3 d^3}\mathscr{K}_3+O_C\Bigl(\frac{x^{1+o(1)}}{D N_1}\Bigr),
\end{align*}
where
\begin{align*}
\mathscr{K}_3:&=\sum_{\substack{q\sim Q\\ (q,a d)=1}}\frac{Q^3 c_q}{q^3}\sum_{\substack{m\sim M\\ (m,q d)=1}}\alpha_m\sum_{\substack{1\le |h_1|\le H_1 \\ 1\le |h_2|\le H_2\\ 1\le |h_3|\le H_3}}\hat{\psi_1}\Bigl(\frac{N_1 h_1}{q d}\Bigr)\hat{\psi_2}\Bigl(\frac{N_2h_2}{q d}\Bigr)\hat{\psi_3}\Bigl(\frac{N_3h_3}{q d}\Bigr)\\
&\qquad\times\sum_{\substack{b_1,b_2,b_3\in(\mathbb{Z}/q d\mathbb{Z})^\times\\ b_1b_2b_3\equiv a\overline{m}\Mod{q d}}}e\Bigl(\frac{h_1b_2+h_2b_2+h_3b_3}{q d}\Bigr).
\end{align*}

Thus $\mathscr{K}'$ is given by
\begin{align*}
\mathscr{K}'=&\sum_{\substack{1\le d_0\le H_1\\ (d_0,ad)=1}}\sum_{\substack{1\le d_1\le Q/d_0\\ (d_1,ad)=1}}\mu^2(d_0 d_1)\sum_{\substack{1\le e_1\le H_1/d_0\\ 1\le e_2\le H_2/d_0\\ 1\le e_3\le H_3/d_0\\ (e_1e_2e_3,d_1)=d_1\\ (e_1,e_2,e_3)=1\\ e_i|d_1\,\forall i}}H(e_1,e_2,e_3;d_1)\sum_{\substack{Q/d_0d_1\le q''\le Q'/(d_0d_1)\\ (q'',e_1e_2e_3)=1}}c'_{d_0 d_1 q''}\\
&\times\sum_{\substack{m\sim M\\ (m,q'' d_0d_1)=1}}\alpha'_m\sum_{\substack{1\le |h_1''|\le H_1/d_0e_1\\ 1\le |h_2''|\le H_2/d_0e_2 \\ 1\le |h_3''|\le H_3/d_0e_3\\ d_0 e_i h_i''\equiv b_i\Mod{d}\,\forall i\\  (h_i'',d_1/e_i)=1\,\forall i\\ (h_i'',q'')=1\,\forall i}}\phi(d_0)^2q'' \mathrm{Kl}_3\Bigl(d_0^2e_1e_2e_3h_1''h_2''h_3''a\overline{m d^3 d_1{}^3};q''\Bigr).
\end{align*}

Let $H_i':=H_i/d_0e_i$. We recall that $H(e_1,e_2,e_3)\ll e_1e_2e_3/d_1$. Then we have
\begin{align*}
\mathscr{K}'\ll & Q\sum_{\substack{1\le d_0\le x\\ 1\le d_1\le x}}\frac{d_0\mu^2(d_0 d_1)}{d_1}\sum_{\substack{e_1,e_2,e_3 \\ e_i|d_1 \forall i}}\frac{e_1 e_2 e_3}{d_1}\sup_{\substack{Q/d_0d_1\le Q''\le Q'''\le Q'/d_0d_1\\ b_1'',b_2'',b_3''\Mod{d}}}|\mathscr{K}'_2|,
\end{align*}
where $\mathscr{K}'_2=\mathscr{K}'_2(d_0,d_1,e_1,e_2,e_3)$ is given by
\begin{align*}
\mathscr{K}'_2&:=\sum_{\substack{Q''\le q''\le Q'''\\ (q'',e_1e_2e_3)=1}}\tilde{c}_{q''}\sum_{\substack{m\sim M\\ (m,q''d_0d_1)=1}}\alpha'_m\sum_{\substack{1\le |h_1''|\le H_1'\\ 1\le |h_2''|\le H_2' \\ 1\le |h_3''|\le H_3'\\ h_i''\equiv b_i''\Mod{d}\,\forall i\\ (h_i'',d_1/e_i)=1\,\forall i\\ (h_i'',q'')=1\,\forall i}}\mathrm{Kl}_3\Bigl(f_1 h_1''h_2''h_3''\overline{m f_2};q''\Bigr),
\end{align*}
where $f_1=a e_1e_2e_3$ and $f_2=d^3d_1^3$ and $\tilde{c}_{q''}=d_0d_1q'' c_{q''d_0 d_1}/(2Q)$.

In order to establish the result (recalling $M N_1 N_2 N_3\asymp x$ and $H_i\ll x^{2\epsilon} QR/(d_0e_i N_i)$), we see it is sufficient to show
\begin{equation}
\mathscr{K}_2''\ll \frac{Q R^2M x^{1-7\epsilon} d_1^6 d_0^2}{e_1 e_2 e_3^2 N_3}. \end{equation}

For the `diagonal terms' with $r_2^3 h_3'm_1= r_2^3 h_3 m_2$, we use the `trivial bound' $\mathscr{K}_3''\ll x^{o(1)}H$ which follows from Lemma \ref{lmm:Deligne}. Given $r_1,h_3',m_1$ there are $x^{o(1)}$ choices of $r_2,h_3$ and $m_2$. Thus these terms contribute to $\mathscr{K}_2''$ a total
\begin{align}
\ll\sum_{q\sim Q}\sum_{r_1\sim R}\sum_{1\le |h_3'|\le H_3}\sum_{m_1\sim M}x^{o(1)} H
&\ll x^{o(1)}Q R M H_1 H_2 H_3\nonumber\\
&\ll x^{7\epsilon}\frac{Q^4 R^4 M}{N_1 N_2 N_3 d_0^3 e_1e_2e_3}\nonumber\\
&\ll \frac{Q^4 R^4 M^2}{x^{1-7\epsilon} d_0^3 e_1e_2e_3}. \end{align}

We now consider the terms when $r_1^3 h_3' m_1\ne r_2^3 h_3 m_2$. In this situation we apply Lemma \ref{lmm:KloostermanCorrelation}, which gives that 
\begin{equation}
\mathscr{K}_4'\ll x^\epsilon Q^{1/2} R d_3+\frac{x^{\epsilon}H_1 H_2 }{Q^{1/2}[r_1,r_2]^{1/2}}d_3 d_4, \end{equation}
where $d_3=d_3(q,r_1,r_2,m_1,m_2,h_3,h_3')$ and $d_4=d_4(r_1,r_2,h_3'm_1-h_3m_2)$ are given by
\begin{align*}
d_3&=\gcd(r_1^3 h_3'm_1-r_2^3 h_3 m_2,q),\\
d_4&=\gcd(h_3'm_1-h_3m_2,r_1,r_2).
\end{align*}
Thus the contribution of the first term on the right hand side of \eqref{eq:E5Bound} to $\mathscr{K}_3'$ is
\begin{align}
&\ll x^\epsilon Q^{1/2} R \sum_{r_1,r_2\sim R}\sum_{m_1,m_2\sim M} \sum_{\substack{1\le |h_3|,|h_3'|\le H_3\\ r_1^3 h_3'm_1\ne r_2^3 h_3'm_2}}\sum_{q\sim Q}d_3\nonumber\\
&\ll x^\epsilon Q^{3/2}R \sum_{r_1,r_2\sim R}\sum_{m_1,m_2\sim M} \sum_{\substack{1\le |h_3|,|h_3'|\le H_3\\ r_1^3 h_3'm_1\ne r_2^3 h_3'm_2}}\tau(r_1^3 h_3'm_1-r_2^3 h_3m_2)\nonumber\\
&\ll x^{2\epsilon} Q^{3/2} R^3 M^2 H_3^2\nonumber\\
&\ll x^{6\epsilon} \frac{M^2 Q^{7/2} R^5}{N_3^2 e_3^2 d_0^{2}}. \end{align}
The contribution from the last term on the right hand side of \eqref{eq:E5Bound} to $\mathscr{K}_3'$ is
\begin{align}
&\ll \frac{x^\epsilon H_1H_2}{Q^{1/2} R}\sum_{1\le |h_3|,|h_3'|\le H_3}\sum_{\substack{m_1,m_2\sim M\\ r_1^3 h_3' m_1\ne r_2^3 h_3m_2}}\sum_{\substack{r_1,r_2\sim R}}(r_1,r_2)^{1/2}d_4\sum_{q\sim Q}d_3\nonumber\\
&\ll x^{2\epsilon} \frac{H_1 H_2}{Q^{1/2}R} R^2 H_3^2 M^2 Q\nonumber\\
&\ll \frac{Q^{9/2} R^5 M^3}{e_1e_2e_3 d_0^{4} x^{1-10\epsilon}N_3 }. \end{align}

This bound now follows from Lemma \ref{lmm:K3} provided we have
\begin{align*}
\frac{M' Q_1''{}^{5/2}Q_2''{}^3}{x^{1-14\epsilon}}&\le N_3'\le \frac{x^{2-14\epsilon}}{Q_1''{}^3Q_2''{}^2 M'},\\
M'{}^2 Q_1''{}^{7/2}Q_2''{}^3&<x^{2-20\epsilon}.
\end{align*}
Since $N_3'=N_3x^{o(1)}$ and $Q_i''\le Q_i'\le Q_i$ and $M'=M x^{o(1)}$ we see that the above bounds certainly hold provided we have
\begin{align*}
\frac{M Q_1^{5/2}Q_2^3}{x^{1-15\epsilon}}&\le N_3\le \frac{x^{2-15\epsilon}}{Q_1^3Q_2^2 M},\\
M^2 Q_1^{7/2}Q_2^3&<x^{2-21\epsilon}.
\end{align*}

We first apply Lemma \ref{lmm:KRough} with the trivial factorization $Q_1=Q R$, $Q_2=1$. This gives the result provided
\begin{equation}
\frac{M Q^{5/2} R^{5/2} }{x^{1-15\epsilon}}<N_3<\frac{x^{2-15\epsilon} }{Q^3 R^3 M}. \end{equation}

We now apply Lemma \ref{lmm:KRough} with the factorization $Q_1=Q$, $Q_2=R$, which gives the result provided
\begin{equation}
\frac{M Q^{5/2}R^{3}}{x^{1-15\epsilon}}<N_3<\frac{x^{2-15\epsilon}}{Q^3 R^2 M}. \end{equation}

Since $M<x^{1-20\epsilon} Q^{-15/8}R^{-15/8}$, we see that 
\begin{equation}
\frac{M Q^{5/2} R^{5/2}}{x^{1-15\epsilon}}<\frac{x^{1/3-\epsilon}}{M^{1/3}}. \end{equation}

Since $M<x^{1-20\epsilon} Q^{-15/8}R^{-15/8}$ and $Q^9 R<x^{32/7}$, we have
\begin{equation}
\frac{x^{2-15\epsilon}}{M Q^3 R^2}>\frac{x^{1+\epsilon} }{Q^{9/8}R^{1/8}}>x^{3/7+\epsilon}. \end{equation}
